    "questionText": "Aşağıda Türkiye'deki bazı şehirler ve gelişimlerinde öne çıkan fonksiyonlar eşleştirilmiştir.\nBu eşleştirmelerden hangisi yanlıştır?",
    "options": {
      "A": "İzmir – Liman ve Ticaret",
      "B": "Ereğli – Sanayi",
      "C": "Bodrum – Turizm",
      "D": "Konya – Tarım ve Ticaret",
      "E": "Çanakkale – Ticaret ve Finans"
    },
    "markedAnswer": "A",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Çanakkale – Ticaret ve Finans\nÇanakkale ili; stratejik Çanakkale Boğazı konumu, 1915 Çanakkale Şehitlikleri ve Troya Antik Kenti ile **\"Askeri, Geçiş ve Tarihi Turizm\"** fonksiyonları ile öne çıkan bir kenttir. Türkiye'nin ticaret ve finans fonksiyonunu üstlenen metropolü ise tartışmasız **İstanbul**dur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İzmir – Liman ve Ticaret: Ege'nin en büyük ihracat limanı ve fuarlar şehridir (Doğrudur).\n• B) Ereğli (Zonguldak) – Sanayi: Erdemir Demir-Çelik Fabrikası sayesinde gelişmiş ağır sanayi kentidir (Doğrudur).\n• C) Bodrum (Muğla) – Turizm: Türkiye'nin uluslararası düzeydeki en önemli deniz ve kültür turizmi merkezidir (Doğrudur).\n• D) Konya – Tarım ve Ticaret: Türkiye'nin tahıl ambarı olup tarıma dayalı ticaret ve gıda sanayisi gelişmiştir (Doğrudur).\n\n💡 KPSS HAFIZA KARTI:\nŞehir Fonksiyonları Eşleştirmeleri:\n• İskenderun, Karabük, Ereğli = **Ağır Sanayi**\n• Batman, Elazığ/Maden, Soma = **Madencilik**\n• Rize, Giresun, Akhisar = **Tarım**\n• Mersin, Trabzon, İzmir = **Liman / Dış Ticaret**",
