    "questionText": "Türkiye'nin en büyük hidroelektrik barajları Atatürk, Karakaya, Keban, Ilısu, Altınkaya, Birecik ve Deriner santralleridir.\n\nYukarıdaki barajların santralleri dikkate alındığında aşağıdaki illerden hangisinde hidroelektrik üretimin daha az olduğu söylenir?",
    "options": {
      "A": "Şanlıurfa",
      "B": "Artvin",
      "C": "Mardin",
      "D": "Iğdır",
      "E": "Samsun"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Iğdır\nIğdır ili, Doğu Anadolu'nun en alçak tektonik çöküntü ovasıdır (Sürmeli Ovası - 850 m rakım). Düz bir ova tabanında yer aldığı ve etrafı yüksek dağlarla çevrili mikroklima alanı olduğu için hidroelektrik baraj yapımına uygun bir vadi yapısı ve eğimi bulunmaz; **Iğdır'da büyük bir hidroelektrik santral (HES) yoktur**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Şanlıurfa: Türkiye'nin en büyük barajı olan **Atatürk Barajı** ve Birecik Barajı'na ev sahipliği yapar.\n• B) Artvin: Çoruh Nehri üzerinde Türkiye'nin en yüksek gövdeli barajları olan **Deriner Barajı ve Yusufeli Barajı**na ev sahipliği yapar.\n• C) Mardin: Dicle Nehri üzerindeki devasa **Ilısu (Veysel Eroğlu) Barajı**na ev sahipliği yapar.\n• E) Samsun: Yeşilırmak ve Kızılırmak üzerinde **Altınkaya Barajı ve Hasan Uğurlu Barajı**na ev sahipliği yapar.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'nin En Büyük HES'leri:\n1. Atatürk Barajı (Fırat / Şanlıurfa-Adıyaman)\n2. Karakaya Barajı (Fırat / Malatya-Diyarbakır)\n3. Keban Barajı (Fırat / Elazığ)\n4. Ilısu Barajı (Dicle / Mardin)\n5. Deriner ve Yusufeli Barajları (Çoruh / Artvin - En yüksek kemer gövde).",
    "isMapQuestion": false,
    "file": "20260905_001433.jpg"
