    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Anamur Burnu - Karataş Burnu arası (Mersin-Silifke-Taşeli Kıyıları)\n**Kalanklı Kıyı Tipi (Kanyonlu Kıyı)**; kalkerli karstik arazilerde açılmış derin kanyon vadilerin deniz seviyesinin yükselmesiyle su altında kalması sonucu oluşan girintili çıkıntılı kıyılardır. Türkiye'de en tipik örneği **Mersin-Silifke ile Taşeli Platosu kıyılarında (Anamur-Karataş arası)** görülür.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B & E) Ege Kıyıları (Karaburun, Datça, Edremit): Dağların dik uzandığı tipik **Enine Kıyı Tipi**dir.\n• C) Sinop-Cide arası (Karadeniz): Dağların paralel uzandığı **Boyuna Kıyı Tipi**dir.\n• D) Kaş - Ölüdeniz arası (Antalya-Muğla): Dağların kıyıya paralel adacıklar oluşturduğu **Dalmaçya Kıyı Tipi** ve Ria tipi kıyılardır.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'de Görülen Kıyı Tipleri:\n• Boyuna Kıyı: Karadeniz ve Akdeniz\n• Enine Kıyı: Ege Bölgesi\n• Ria Kıyı: İstanbul ve Çanakkale Boğazları, Haliç, Menteşe Kıyıları\n• Dalmaçya Kıyı: Antalya / Kaş-Finike kıyıları\n• Kalanklı Kıyı: Mersin / Silifke kıyıları\n• Limanlı Kıyı: Büyük ve Küçük Çekmece kıyıları.\n(NOT: Fiyort, Skayer ve Haliç kıyı tipi Türkiye'de YOKTUR!).",
