    "questionText": "Yer şekillerinin meydana getiren olaylar oldukça karmaşıktır. Bir süreç oluşumu esnasında başka bir oluşumu da meydana getirebilmektedir.\nI. Van Gölü'nün oluşumu\nII. Akyatan Lagünü'nün oluşumu\nIII. Bafra Deltası'nın oluşumu\nIV. Manavgat Şelalesi'nin oluşumu\n\nYukarıda verilen oluşumlardan hangileri birden fazla sürecin iç içe geçmesi ile meydana gelmiştir?",
    "options": {
      "A": "I ve II",
      "B": "I ve III",
      "C": "II ve III",
      "D": "II ve IV",
      "E": "III ve IV"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) I ve II (Van Gölü ve Eğirdir Gölü)\nYer şekillerinin oluşumunda birden fazla dış veya iç kuvvetin birlikte rol oynadığı göllere \"Karma Oluşumlu Göller\" denir:\n• **I. Van Gölü:** Tektonik bir çöküntü alanının önünün Nemrut Dağı'ndan çıkan volkanik lavlar tarafından kapatılmasıyla oluşmuştur (**Tektonik + Volkanik Set**).\n• **II. Eğirdir Gölü:** Akdeniz Bölgesi'nde hem faylanma (tektonizma) hem de kalkerin erimesiyle oluşmuştur (**Tektonik + Karstik**).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• III. Akyatan Lagünü (Adana): Seyhan ve Ceyhan deltalarında dalgaların kıyı kordonuyla koyun önünü kapatmasıyla oluşan saf kıyı set gölüdür (Tek oluşum).\n• IV. Nemrut Krater Gölü: Nemrut Dağı volkanik patlaması sonucu oluşan kaldera gölüdür (Tek oluşum).\n• V. Tortum Gölü: Heyelan kütlesinin vadiyi tıkamasıyla oluşan heyelan set gölüdür (Tek oluşum).\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'deki Karma Oluşumlu Göller:\n1. **Van Gölü** (Tektonik + Volkanik Set)\n2. **Eğirdir ve Kovada Gölleri** (Tektonik + Karstik)\n3. **Beyşehir Gölü** (Tektonik + Karstik).",
