    "explanation": "✅ DOĞRU CEVAP: B) Asi Nehri\nLübnan'daki Bekaa Vadisi'nden doğup Suriye'yi geçerek Hatay'dan Akdeniz'e dökülen **Asi Nehri**, Akdeniz iklim sahasında akmakta olup ana beslenme kaynağı kış yağmurları ve karstik yer altı kaynaklarıdır; **kar erimeleri Asi Nehri'nin beslenmesinde etkili bir faktör değildir**. Çoruh, Aras, Kızılırmak ve Sakarya nehirleri ise Doğu Anadolu ve İç Anadolu'nun 2500-3000 metrelik yüksek karlı dağlarından doğduğu için ilkbahar-yaz aylarında eriyen karlarla coşkun akarlar.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Çoruh Nehri: Mescit Dağları ve Kaçkarların kar ve buzul erimeleriyle beslenir (Rafting cennetidir).\n• C) Kızılırmak: Sivas Kızıldağ'ın karlarıyla beslenir.\n• D) Sakarya Nehri: İç Ege ve İç Anadolu dağlarının kar erimeleriyle beslenir.\n• E) Aras Nehri: Bingöl ve Erzurum dağlarının yüksek kar örtüsüyle beslenir.\n\n💡 KPSS HAFIZA KARTI:\nYurt Dışından Doğup Ülkemizden Denize Dökülen Akarsular (2 Tane):\n1. **Meriç Nehri** (Bulgaristan'dan doğar, Ege'ye dökülür)\n2. **Asi Nehri** (Lübnan'dan doğar, Akdeniz'e dökülür).\n(Tersine bizden doğup dışarı gidenler: Fırat, Dicle, Aras, Kura, Çoruh).",
