    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Türkiye'de maki üst sınırı Akdeniz'de 800 metrelerde iken Marmara'da 200 metrelerdedir.\nCoğrafya biliminin en temel ve ayırt edici ilkesi **\"DAĞILIŞ İLKESİ\"**dir. Dağılış ilkesi; incelenen bir coğrafi olayın yeryüzündeki mekanını, nerede bulunduğunu, yayılış sahasını ve sınırlarını harita üzerinde gösterir. \"Maki üst sınırının Akdeniz'de 800 metre, Ege'de 500 metre, Marmara'da ise 200 metrede olması\" bitki örtüsünün enleme göre mekânsal yayılış sınırlarını ifade ettiği için doğrudan dağılış ilkesidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A & B) Jeolojik yapı ve dağ oluşumları: Neden-sonuç (nedensellik) ilkesidir.\n• C) Mevsim geçişlerinin belirginliği: Karşılıklı ilgi ve nedensellik ilkesidir.\n• E) Kışın kutbi hava kütleleri etkisi: Nedensellik ilkesidir.\n\n💡 KPSS HAFIZA KARTI:\nCoğrafyanın 3 Temel İlkesi:\n1. **Dağılış İlkesi** = Nerede? Hangi sahada? (Yalnızca coğrafyaya özgüdür, harita ile ifade edilir).\n2. **Nedensellik İlkesi** = Neden? Niçin?\n3. **Karşılıklı İlgi (Bağlantı) İlkesi** = Olaylar arası ilişki ve etkileşim.",
