    "explanation": "✅ DOĞRU CEVAP: A) I ve II\nKaradeniz İklimi; her mevsim yağışlı, yıllık sıcaklık farkı az, yazları serin ve ılık geçen iklimdir. Marmara Bölgesi'nde bu iklim tipi:\n• **I. Yıldız Dağları'nın Karadeniz'e bakan kuzey yamaçlarında (Kırklareli/Demirköy kıyıları)**\n• **II. Boğazlar ve Karadeniz kıyı şeridinde (Şile, Sarıyer, Kocaeli kıyıları)** görülür.\nIII (Güney Marmara/Bursa-Balıkesir) Akdeniz iklimi; IV (Ergene Havzası/Edirne) ise Karasal iklim sahasıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I ve II: Karadeniz iklim kuşağı (Gür ormanlar ve bol nem).\n• III: Akdeniz iklimi (Zeytin ve maki toplulukları).\n• IV: Ergene karasal iklimi (Bozkır ve ayçiçeği-buğday tarımı).\n\n💡 KPSS HAFIZA KARTI:\nMarmara Bölgesi = Türkiye'nin İklim Geçiş Bölgesidir!\nAynı bölgede 3 farklı iklim görülür:\n1. Kuzeyinde -> Karadeniz İklimi\n2. Güneyinde -> Akdeniz İklimi\n3. İç/Ergene kısmında -> Karasal Bozkır İklimi.",
