    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Elâzığ - Malatya\nTürkiye'de tatlı su kültür balıkçılığı (özellikle baraj göllerinde kafeslerde alabalık yetiştiriciliği); Fırat Nehri üzerinde kurulu devasa **Keban Baraj Gölü (Elazığ) ve Karakaya Baraj Gölü (Malatya-Diyarbakır)** sayesinde en çok **ELAZIĞ VE MALATYA** illerinde yapılmaktadır. Elazığ, denizi olmadığı halde Türkiye'nin en çok alabalık ihraç eden illerinden biridir!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Deniz Kültür Balıkçılığı (Levrek ve Çipura): En çok **Muğla ve İzmir** kıyılarında yapılır.\n• Tatlı Su Kültür Balıkçılığı (Alabalık): En çok **Elazığ ve Malatya** baraj göllerinde yapılır.\n• Doğal Deniz Balıkçılığı Avcılığı: %70 pay ile **Karadeniz** ilk sıradadır.\n\n💡 KPSS HAFIZA KARTI:\nKültür Balıkçılığı Ayrımı:\n• Denizde Kafes Balıkçılığı = **Muğla** (Koy ve körfezler)\n• Tatlı Suda Alabalık Üretimi = **Elazığ** (Keban Barajı).",
