    "topic": "Türkiye'de Doğa Koruma / Sulak Alanlar (Ramsar Alanları)",
    "questionText": "Türkiye'de tarım alanlarının genişletilmesi için bataklıkların kurutulması planlanmış ve sulak alanları besleyen akarsular üzerine barajlar yapılarak bu konuda çalışmalar yapılmıştır. Bu durum ekosistemde önemli bozulmalara neden olmuş, hatta milli parklara zarar vermiştir.\n\nDevlet Su İşleri Genel Müdürlüğü tarafından Kayseri'de yürütülen Develi Projesi aşağıdaki sulak alanlardan hangisine zarar vermiştir?",
    "options": {
      "A": "Sultan Sazlığı",
      "B": "Seyfe Gölü",
      "C": "Manyas Gölü",
      "D": "Beyşehir Gölü",
      "E": "Eğirdir Gölü"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Sultan Sazlığı\nKayseri'nin Develi Kapalı Havzası'nda yer alan, Afrika ile Avrupa arasındaki göçmen kuşların en kritik uğrak yerlerinden biri olan ve uluslararası **RAMSAR Sözleşmesi** ile korunan **Sultan Sazlığı Millî Parkı**; DSİ'nin bölgede tarım arazisi açmak ve sulama sağlamak amacıyla yürüttüğü Develi Projesi (barajlar ve drenaj kanalları) sebebiyle kuruma noktasına gelmiş ve ekosistemi ağır tahribata uğramıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Seyfe Gölü: Kırşehir'de bulunan önemli bir Ramsar alanıdır; flamingoların üreme alanıdır ancak Develi projesinden değil bölgedeki kaçak kuyulardan etkilenmektedir.\n• C) Manyas (Kuş) Gölü: Balıkesir-Bandırma'da Türkiye'nin ilk Ramsar alanlarındandır; sanayi atıkları ve tarımsal kirlilik tehdidi altındadır.\n• D) Beyşehir Gölü: Konya-Isparta sınırında Türkiye'nin en büyük tatlı su gölü ve millî parkıdır.\n• E) Eğirdir Gölü: Isparta'da yer alan ikinci büyük tatlı su gölüdür.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'nin Önemli Ramsar Alanları:\n• **Göksu Deltası (Mersin)** -> Türkiye'nin İLK Ramsar Alanı (1994).\n• **Sultan Sazlığı (Kayseri)** -> Develi Projesi ile tehdit altına giren Ramsar alanı.\n• **Seyfe Gölü (Kırşehir), Manyas (Balıkesir), Burdur Gölü, Nemrut Kalderası (Bitlis)**.",
