    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Karabük\nOrman Genel Müdürlüğü (OGM) resmi verilerine göre Türkiye'de kendi il sınırları yüz ölçümüne oranla **ORMAN ORANI EN YÜKSEK İLİMİZ %71,5 İLE KARABÜK**'tür (Karabük'ü Muğla, Kastamonu ve Bolu takip eder).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Rize: Bol yağış almasına rağmen yüksek yamaçlar çay tarımı, dik kayalıklar ve alpin çayırlarla kaplı olduğu için orman oranı Karabük'ten düşüktür (%45 civarı).\n• C) Muğla: Yüz ölçümünün yaklaşık %68'i ormandır; Karabük'ün ardından Türkiye ikincisidir.\n• D) Erzurum: Karasal iklim ve yüksek plato şartları nedeniyle orman varlığı son derece kısıtlıdır.\n• E) Iğdır: Yarı kurak mikrokliması ve rüzgar erozyonu nedeniyle orman oranı **TÜRKİYE'NİN EN DÜŞÜK İLİDİR** (%0,2).\n\n💡 KPSS HAFIZA KARTI:\nOrman İstatistikleri Tuzakları:\n• İl Yüz Ölçümüne Göre En Yüksek Oran: **Karabük (%71,5)**\n• Hektar (Miktar / Alan) Olarak En Çok Orman: **Antalya** (2. Kastamonu, 3. Muğla)\n• Orman Oranı En Düşük İl: **Iğdır (%0,2)**\n• Bölgesel Sıralama: En çok orman **Karadeniz Bölgesi**, en az orman **Güneydoğu Anadolu Bölgesi**.",
