    "explanation": "✅ DOĞRU CEVAP: A) Yalnız IV (Çalışanların yaş ortalaması yükselecektir)\nTürkiye nüfusu \"Demografik Fırsat Penceresi\"nin sonuna yaklaşmış ve hızla yaşlanan nüfus yapısına geçmiştir (Doğurganlık hızı 1,51'e gerilemiştir). Gelecek projeksiyonlarına göre:\n• Genç nüfus girişi azaldığı ve ortalama yaşam süresi uzayıp emeklilik yaşı yükseldiği için **ÇALIŞANLARIN YAŞ ORTALAMASI YÜKSELECEKTİR (IV doğru)**.\n• I. Yanlış: Doğumlar azaldığı için ortanca yaş düşmez, **HIZLA YÜKSELİR**.\n• II. Yanlış: Yaşlı nüfusun toplam nüfustaki payı azalmaz, **%10'U GEÇMİŞTİR VE ARTMAYA DEVAM EDECEKTİR**.\n• III. Yanlış: Tıp ve sağlık hizmetleri geliştiği için bebek ölüm oranları artmaz, **AZALIR**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Ortanca yaş: Türkiye'de ortanca yaş 34'ün üzerine çıkmıştır ve gelecekte 40'ı aşacaktır.\n• II. Yaşlı nüfus: 65 yaş üzeri nüfus oranı %10,2'ye ulaşmış olup Türkiye resmen \"Çok Yaşlı Nüfuslu Ülke\" statüsüne girmiştir.\n• III. Bebek ölüm oranı: Binde 9 düzeylerine inmiş olup düşüş eğilimindedir.\n• IV. Çalışanların yaşlanması: Genç iş gücü arzı daraldığından istihdamın yaş ortalaması mecburen yükselecektir.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye Nüfusunun Gelecek Eğilimleri:\n• Doğum ve Doğurganlık Hızı = **DÜŞÜYOR**\n• Nüfus Artış Hızı = **DÜŞÜYOR**\n• Ortanca Yaş = **YÜKSELİYOR**\n• Yaşlı Nüfus Oranı = **YÜKSELİYOR**",
    "isMapQuestion": false,
