    "questionText": "Güneydoğu Anadolu Bölgesi, İç Anadolu Bölgesi, Ege Bölgesi ve Çanakkale-Gökçeada civarında rastlanan, genellikle küçükbaş hayvancılık yapılan, bazı yörelerde 'dönemsel' bazı yörelerde ise 'sürekli' yerleşme özelliği gösteren köy altı yerleşmesi aşağıdakilerden hangisidir?",
