    "explanation": "✅ DOĞRU CEVAP: C) Dam\nEge Bölgesi, İç Anadolu, Güneydoğu Anadolu ve özellikle Çanakkale (Gökçeada ve Bozcaada) yöresinde yaygın olan; küçükbaş hayvancılık ve yer yer bağ-bahçe tarımının yapıldığı, bazı yörelerde sadece hayvan otlatma döneminde geçici, bazı yörelerde ise zamanla ailelerin sürekli yerleştiği köy altı yerleşme tipi **DAM**dır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Ağıl: Koyun ve keçilerin gece barınması için etrafı çit veya taş duvarla çevrili, üstü açık/yarı açık, kesinlikle GEÇİCİ yerleşmedir (İç ve Doğu Anadolu).\n• B) Kom: Doğu Anadolu'da (Erzurum-Kars) büyükbaş hayvancılık yapılan, taş barınak ve ot ambarından oluşan GEÇİCİ yerleşmedir.\n• D) Mezra: Doğu ve Güneydoğu Anadolu'da tarım ve hayvancılığın birlikte yapıldığı, genellikle **SÜREKLİ (KALICI)** olan en yaygın köy altı yerleşmesidir.\n• E) Dalyan: Ege ve Akdeniz kıyılarında (Köyceğiz, Muğla vb.) balık üretimi ve avcılığı için kurulan GEÇİCİ yerleşmedir.\n\n💡 KPSS HAFIZA KARTI:\nKöy Altı Yerleşmeleri Sınıflaması:\n• **Sürekli (Kalıcı) Yerleşmeler:** **\"MADEN ÇİFTLİĞİ\"** -> **M**ezra, **M**ahalle, **D**ivan (Batı Karadeniz), **Ç**iftlik.\n• **Geçici Yerleşmeler:** Yayla (En yaygın), Kom (Doğu Anadolu - büyükbaş), Ağıl (küçükbaş), Oba (Çadır - Yörükler), Dalyan (Balıkçılık), Dam (Ege-Çanakkale).",
