    "topic": "Türkiye Ekonomisi ve Dış Ticaret",
    "questionText": "Türkiye'de 1980 yılından günümüze kadar geçen süreçte dış ticaret hacmi sürekli bir artış göstermiştir.\nBu artışta aşağıdakilerden hangisinin etkili olduğu söylenemez?",
    "options": {
      "A": "İhracata dayalı sanayileşme politikasının benimsenmesi",
      "B": "Ulaşım ve lojistik altyapısının gelişmesi",
      "C": "Serbest ticaret bölgelerinin kurulması",
      "D": "İhracatta tarımsal ve hammadde payının yükselmesi",
      "E": "Yeni pazarlara açılınması ve dış ticaret anlaşmaları"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) İhracatta tarımsal ve hammadde payının yükselmesi\n1980 yılında alınan \"24 Ocak Kararları\" ile Türkiye dışa kapalı ithal ikameci modeli terk edip ihracata dayalı sanayileşme modeline geçmiştir. Bu süreçte Türkiye'nin toplam ihracatında sanayi ürünlerinin (otomotiv, tekstil, beyaz eşya, kimya) payı %94'lere yükselmiştir. Hammadde ve tarımsal ürünlerin toplam ihracattaki oransal payı ise %70'lerden %6-8'lere **GERİLEMİŞTİR**. Gelişen ekonomiler işlenmemiş hammadde satmaz; hammadde ithal edip yüksek katma değerli işlenmiş mamul ihraç eder!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İhracata dayalı sanayileşme: Üretilen sanayi mallarının yurt dışına satılması ticaret hacmini patlatmıştır.\n• B) Ulaşım ve lojistik altyapı: Otoyollar, modern limanlar ve hava kargo taşımacılığı dış ticareti hızlandırmıştır.\n• C) Serbest bölgeler: Vergi muafiyetleri ve gümrüksüz ticaretle ihracata dev katkı sağlamıştır (Mersin, Ege Serbest Bölgesi vb.).\n• E) Dış ticaret anlaşmaları: Gümrük Birliği ve yeni serbest ticaret anlaşmaları pazar payını artırmıştır.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye'nin Dış Ticaret Röntgeni:\n• İhracatta 1. Sektör: **Sanayi (%94 civarı)** (Tarım %5, Madencilik %2).\n• İhracatta 1. Kalem: **Motorlu Kara Taşıtları (Otomotiv)**.\n• İhracatta 1. Ülke: **Almanya**.\n• İthalatta 1. Ülkeler: **Rusya, Çin, Almanya** (En çok enerji ve makine ithal edilir).",
