    "questionText": "Aşağıdaki Türkiye haritasında beş alan numaralarla gösterilmiştir.\n[Haritada I: Kastamonu (Küre), II: Marmara Adası / Balıkesir, III: Antalya (Akseki) / Konya (Seydişehir), IV: Hakkari yöresi, V: Ankara (Beypazarı) gösterilmiştir]\n\n• Trona (Soda Külü)\n• Mermer\n• Boksit\n• Bakır\n\nVerilen madenler ile haritadaki numaralı yerler eşleştirildiğinde hangisi dışarıda kalır?",
