    "topic": "Türkiye'de Ulaşım / Demiryolu Ağı",
    "questionText": "Türkiye'de demir yolu ağı dikkate alındığında aşağıdakilerden hangisi yanlıştır?",
    "options": {
      "A": "Doğu Karadeniz illerinin tamamına demir yolu ağı yoktur.",
      "B": "Irak'a demir yolu sınır kapısı bulunmamaktadır.",
      "C": "Van Gölü üzerinde feribot ile sağlanmaktadır.",
      "D": "Ankara - İzmir arasında YHT ile sağlanmaktadır.",
      "E": "Antalya ve Muğla illerine yer şekillerinden dolayı gitmemektedir."
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Ankara - İzmir arasında YHT ile sağlanmaktadır\nAnkara - Afyonkarahisar - Uşak - Manisa - İzmir Yüksek Hızlı Tren hattı halen inşaat aşamasında olup henüz hizmete açılmamıştır. Mevcut durumda Ankara ile İzmir arasında doğrudan bir YHT seferi YOKTUR.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Doğu Karadeniz demir yolu: Artvin, Rize, Trabzon ve Giresun illerinin hiçbirinde sarp dağlar ve engebe nedeniyle demir yolu ağı yoktur (Doğru).\n• B) Irak demir yolu sınırı: Habur Sınır Kapısı yalnızca kara yolu sınırıdır; Türkiye'nin Irak ile hiçbir demir yolu bağlantısı yoktur (Doğru).\n• C) Van Gölü feribotu: Tatvan ile Van iskelesi arasında tren vagonları göl üzerinden feribotla taşınarak İran hattına bağlanır (Doğru).\n• E) Antalya ve Muğla: Teke ve Taşeli platoları ile Menteşe yöresinin aşırı engebeli karstik yapısı nedeniyle bu illerimize tren gitmez (Doğru).\n\n💡 KPSS HAFIZA KARTI:\nDemir Yolu Gitmeyen Önemli İllerimiz:\n• Doğu Karadeniz Kıyı Kuşağı: **Trabzon, Rize, Artvin, Giresun, Ordu**\n• Akdeniz ve Güney Ege Kıyısı: **Antalya ve Muğla**\n• Diğer Önemli Merkezler: **Çanakkale, Sinop, Hakkari, Bartın, Kastamonu**\n• Sınır Kapıları Notu: **Irak'a demir yolu sınır kapısı YOKTUR!**",
    "isMapQuestion": false,
