    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Mukan Kağan\nI. Göktürk (Köktürk) Devleti'nin en parlak dönemi Mukan Kağan dönemidir. Doğuda Moğol kökenli Kitanları, kuzeyde Türk kökenli Kırgızları hâkimiyet altına alarak Türk siyasi birliğini büyük oranda sağlamış, sınırları Hazar Denizi'ne kadar genişletmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Kutluk Kağan: II. Göktürk Devleti'nin kurucusudur. 50 yıllık Çin esaretine son verip dağınık boyları bir araya getirdiği için kendisine \"derleyen, toplayan\" anlamında \"İlteriş\" unvanı verilmiştir.\n• B) İşbara Kağan: I. Göktürk Devleti'nin zayıflama ve iç karışıklık döneminde tahta çıkmıştır; Çin İmparatoru'na yazdığı ünlü mektupta Türk adetlerini asla değiştirmeyeceğini bildirmiştir.\n• C) Bumin Kağan: Avar egemenliğine son vererek 552'de Ötüken merkezli I. Göktürk Devleti'ni kuran hükümdardır (\"İl Kağan\" unvanını almıştır).\n• E) Kapgan Kağan: II. Göktürk Devleti hükümdarıdır. \"Fatih\" unvanıyla Çin'e 25'ten fazla sefer düzenlemiş, Çin'i vergiye bağlamış ve tarım tohumu alarak iktisadi kalkınmayı sağlamıştır.\n\n💡 KPSS HAFIZA KARTI:\nI. Göktürk Devleti kurucusu: Bumin Kağan | En parlak dönem: Mukan Kağan\nII. Göktürk (Kutluk) kurucusu: Kutluk (İlteriş) Kağan | En parlak dönem: Bilge Kağan",
