    "topic": "İlk Türk Devletleri / Kültür ve Medeniyet (Protokol ve Paylaşım)",
    "questionText": "1. İlk Türk devletlerinde yöneticiler arasında belirli bir protokol uygulanmıştır. Örneğin hükümdarın bulunduğu kurultay ve bu mecliste kimin nerede oturacağı, kime hangi yemeklerin verileceği belirli kurallara bağlanmıştır. Bu metinde aşağıdaki kavramlardan hangisine dair açıklama yapılmıştır?",
    "options": {
      "A": "Kut",
      "B": "Yabgu",
      "C": "Ayukı",
      "D": "Ülüş",
      "E": "Kızıl Elma"
    },
    "markedAnswer": "C",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Ülüş\n\"Ülüş\", eski Türkçede \"paylaşmak, üleşmek\" kökünden gelir. Kurultaydaki oturma düzeni (orun), av etlerinin paylaşımı ve şölenlerde boy beylerine verilen et payı belirli protokole bağlanmıştır. Bu paylaşım hakkına ve ilahi zenginlik payına \"ülüş\" denir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Kut: Devleti yönetme yetkisinin Gök Tengri tarafından kağana ve onun hanedanına (erkek soyuna) verildiğine inanılan kutsal inançtır. Taht kavgalarına yol açmıştır.\n• B) Yabgu: İkili devlet teşkilatında batı kanadını yöneten hanedan üyesidir (genellikle kağanın kardeşi). İç işlerinde serbest, dışta kağana bağlıdır.\n• C) Ayukı: İlk Türk devletlerinde \"Hükümet\" (Bakanlar Kurulu) demektir. Başındaki vezire \"Aygucı/Üge\", üyelerine ise \"Buyruk\" (Bakan) denir.\n• E) Kızıl Elma: Türk cihan hâkimiyeti mefkûresini, ulaşılması hedeflenen büyük idealleri ve fethedilmesi arzulanan kutsal beldeleri simgeleyen soyut semboldür.\n\n💡 KPSS HAFIZA KARTI:\nAyukı = Hükümet | Aygucı = Vezir (Başbakan) | Buyruk = Bakan | Orun = Protokoldeki yer | Ülüş = Paylaşım/Hisse",
