    "markedAnswer": "A",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Hunların Kuzey ve Güney olarak ikiye ayrılması\nHunların Kuzey ve Güney olarak ikiye ayrılması M.Ö. 48 yılında (Ho-han-ye ile Çi-çi arasındaki taht ve bağımsızlık kavgası sonucu) yaşanmıştır. 375 yılında başlayan Kavimler Göçü ise bundan yüzyıllar sonradır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Roma İmparatorluğu'nun parçalanması: Kavimler Göçü'nün doğrudan sonucudur. Roma 395'te Doğu ve Batı olarak ikiye ayrılmış, Batı Roma 476'da yıkılmıştır.\n• B) Avrupa'da feodalitenin (derebeylik) ortaya çıkması: Merkezi krallıkların otoritesini kaybetmesi ve halkın şatoların himayesine sığınmasıyla Orta Çağ Avrupası'nın temel düzeni olmuştur.\n• C) Hristiyanlık dininin yaygınlaşması: Barbar Germen kavimleri zamanla Roma topraklarında Hristiyanlığı benimsemiş, kilise ve skolastik düşünce güç kazanmıştır.\n• D) Günümüz Avrupa milletlerinin ortaya çıkması: Vizigotlar (İspanya), Angıllar ve Saksonlar (İngiltere), Franklar (Fransa), Ostrogotlar (İtalya) gibi kavimler bugünkü milletlerin temelini atmıştır.\n\n💡 KPSS HAFIZA KARTI:\n375 Kavimler Göçü: İlk Çağ kapandı, Orta Çağ başladı. Avrupa Hun Devleti (Balamir öncülüğünde) kuruldu.",
