    "category": "İlk Türk-İslam Devletleri",
    "topic": "Türk-İslam Tarihi / Büyük Selçuklu Devleti",
    "questionText": "1055 yılında Bağdat Seferi'ni düzenleyen Büyük Selçuklu Hükümdarı Tuğrul Bey'e, Abbasî Halifesi el-Kaim bi-Emrillah tarafından \"Doğunun ve Batının Sultanı (Şark ve Garpın Sultanı)\" unvanının verilmesinin temel sebebi aşağıdakilerden hangisidir?",
    "options": {
      "A": "Dandanakan Savaşı'nda Gaznelileri mağlup etmesi",
      "B": "Şii Büveyhoğulları tehlikesini bertaraf ederek Halifeyi koruma altına alması",
      "C": "Pasinler Savaşı ile Bizans'ı yenilgiye uğratması",
      "D": "Fatımilere karşı Kudüs'ü fethetmesi",
      "E": "Anadolu'ya yönelik ilk Türk akınlarını başlatması"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Şii Büveyhoğulları tehlikesini bertaraf ederek Halifeyi koruma altına alması\nTuğrul Bey 1055 yılında Bağdat Seferi'ni düzenleyerek Abbasi Halifeliği üzerindeki Şii Büveyhoğulları baskısına ve işgaline son vermiştir. Halife el-Kaim bi-Emrillah, Tuğrul Bey'e iki kılıç kuşatıp \"Doğunun ve Batının Sultanı (Sultan-ı Maşrık ve Mağrib)\" unvanını vererek İslam'ın siyasi liderliğini resmen Türklere devretmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Dandanakan Savaşı (1040): Büyük Selçuklu Devleti'nin resmen kurulduğu, Gaznelilerin ise yıkılış sürecine girdiği savaştır.\n• C) Pasinler Savaşı (1048): Selçuklular ile Bizans ve Gürcü ittifakı arasında yapılan İLK büyük meydan savaşıdır.\n• D) Kudüs'ün Fethi (Fatımilere karşı): Fatımilerden Kudüs'ü Selçuklu komutanı Atsız Bey almıştır; Tuğrul Bey döneminde değil Melikşah dönemindedir.\n• E) Anadolu'ya yönelik ilk Türk akınları: Çağrı Bey'in 1015-1021 yılları arasındaki keşif akınlarıyla başlamıştır.\n\n💡 KPSS HAFIZA KARTI:\n1055 Bağdat Seferi ile İslam dünyasında Dini Liderlik (Halife) ile Siyasi Liderlik (Selçuklu Sultanı) birbirinden ayrılmıştır (Laikleşmenin ilk tohumu sayılır).",
