    "topic": "İlk Türk İslam Devletleri / İslamiyet'in Yayılması",
    "questionText": "Türk-İslam Devletleri, İslam kültür ve medeniyetinin daha geniş alanlara yayılmasına hizmet etmişlerdir.\n\nAşağıdakilerden hangisi bu durumu gösteren bir örnek olarak gösterilebilir?",
    "options": {
      "A": "Selahattin Eyyubi’nin Kudüs’ü Haçlılardan geri alması",
      "B": "Sultan Alparslan’ın Malazgirt Savaşı sonrasında Anadolu’nun kapılarını Türklere açması",
      "C": "Kut anlayışının İslamiyet’ten sonra Allah’ın nasibi şekline dönüşmesi",
      "D": "Tuğrul Bey’in Bağdat Seferi ile Büveyhoğulları Devleti'ne son vermesi",
      "E": "İslamiyet’ten sonra Türklerin büyük çoğunluğunun yerleşik hayata geçmesi"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Sultan Alparslan’ın Malazgirt Savaşı sonrasında Anadolu’nun kapılarını Türklere açması\nİslamiyet'in \"daha geniş alanlara ve yeni coğrafyalara yayılması\" demek; gayrimüslim bölgelerin fethedilerek İslamlaştırılması demektir. Malazgirt Zaferi (1071) ile Hristiyan Bizans kontrolündeki Anadolu fethedilmiş, İslam medeniyeti Anadolu'da kalıcı hale gelmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Selahaddin Eyyubi'nin Kudüs'ü alması (1187 Hıttin Savaşı): Yeni bir bölgeye yayılma değil; daha önce Müslümanların elinde olan bir kutsal beldenin Haçlılardan geri alınması (savunma/kurtarma) niteliğindedir.\n• C) Kut anlayışının Allah'ın takdiri haline gelmesi: Türklerin devlet ve egemenlik anlayışındaki içsel/kültürel değişimdir, coğrafi yayılma değildir.\n• D) Tuğrul Bey'in Bağdat Seferi (1055): Zaten İslam coğrafyası olan Bağdat'ta halifeyi Şii baskısından korumaktır (iç koruma).\n• E) Yerleşik hayata geçiş: Sosyo-ekonomik bir yaşam tarzı değişikliğidir.\n\n💡 KPSS HAFIZA KARTI:\nTürklerin İslamiyet'i Yaydığı Coğrafyalar:\n• Anadolu: Büyük Selçuklu ve Osmanlı\n• Hindistan: Gazneliler (Gazneli Mahmut'un 17 Seferi) ve Babürler\n• Balkanlar: Osmanlı Devleti",
