    "topic": "İlk Türk İslam Devletleri / Karahanlılar Kültür ve Medeniyeti",
    "questionText": "İslamiyet’le birlikte hükümdarlık ünvanlarında da değişiklikler görülmüştür.\n\nBuna göre “Hakan” yerine “Arslan Han”, “Yabgu” yerine “Buğra Han”, “Şad” yerine ise “İlig Han” ünvanlarını kullanan Türk-İslam Devleti aşağıdakilerden hangisidir?",
    "options": {
      "A": "Memlükler",
      "B": "Karahanlılar",
      "C": "Türkiye Selçukluları",
      "D": "Gazneliler",
      "E": "Eyyübiler"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Karahanlılar\nKarahanlılar (840-1212) Orta Asya'da kurulan ilk Müslüman Türk devletidir. İslamiyet'i Satuk Buğra Han (Abdülkerim) döneminde kabul etmelerine rağmen halkı, ordusu ve yönetimi tamamen Türk olduğu için Türkçe'yi resmi dil yapmış; eski Türk unvanlarını (Arslan Han, Buğra Han, İlig Han) koruyarak milli kimliklerini yaşatmışlardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Memlükler (Kölemenler): Mısır'da kurulan devlettir. Hükümdarları \"Sultan\" unvanını kullanmış; veraset sisteminde kut anlayışı yerine \"en güçlü emirin tahta geçmesi\" kuralını uygulamışlardır.\n• C) Türkiye Selçukluları: Fars kültürünün etkisinde kalarak hükümdarlarına Farsça \"Keykavus, Keykubat, Keyhüsrev, Rükneddin\" gibi unvanlar vermişlerdir.\n• D) Gazneliler: İslam dünyasında \"Sultan\" unvanını İLK kez kullanan devlettir (Gazneli Mahmut).\n• E) Eyyübiler: Mısır, Suriye ve Hicaz'da hüküm süren, Selahaddin Eyyubi'nin kurduğu ve hükümdarlarına \"Melik / Sultan\" unvanı veren devlettir.\n\n💡 KPSS HAFIZA KARTI:\nHükümdar Unvanları:\n• Sultan unvanını ilk kullanan: Gazneli Mahmut\n• Keykubat, Keykavus, Keyhüsrev unvanları: Türkiye (Anadolu) Selçukluları\n• Arslan Han, Buğra Han, İlig Han unvanları: Karahanlılar",
