    "explanation": "✅ DOĞRU CEVAP: A) Bizans saldırıları\nBüyük Selçuklu Devleti Bizans'a karşı daima taarruz ve galibiyet pozisyonundadır (Pasinler 1048, Malazgirt 1071). Bizans'ın Selçuklu merkezini yıkacak bir saldırı gücü bulunmamaktadır. Selçuklular Bizans saldırısıyla değil, iç karışıklıklar ve Moğol/Karahitay baskısıyla yıkılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Atabeylerin bağımsızlık çalışmaları: Melikleri eğiten Atabeyler, merkezi otorite zayıflayınca bağımsız beylikler (Zengiler, İldenizoğulları, Salgurlular, Böriler, Begteginliler) kurarak devleti parçalamıştır.\n• C) Taht kavgaları: Geleneksel veraset sistemi (\"ülke hanedanın ortak malıdır\") nedeniyle Sultan Melikşah'ın ölümüyle 11 yıl süren Fetret Devri (Berk-yaruk, Muhammed Tapar, Sencer) yaşanmıştır.\n• D) Oğuz (Türkmen) İsyanı: Devlet kadrolarında İranlıların (Fars kökenlilerin) öne çıkarılmasına öfkelenen göçebe Oğuzlar isyan etmiş, son büyük hükümdar Sultan Sencer'i esir almıştır (1153).\n• E) Batınilerin (Haşhaşiler) zararlı faaliyetleri: Hasan Sabbah liderliğindeki Alamut Kalesi merkezli tarikat, vezir Nizamülmülk dahil birçok Selçuklu liderine suikast düzenleyerek devleti içten çökertmiştir.\n\n💡 KPSS HAFIZA KARTI:\nBüyük Selçuklu'nun Yıkılış Dönüm Noktası: 1141 Katvan Savaşı (Moğol kökenli Karahitaylara yenilgi) ve 1153 Oğuz İsyanı'dır.",
