    "topic": "Türk İslam Devletleri / Eyyubiler",
    "questionText": "1187 yılında Hıttin Savaşı ile Haçlıları mağlup ederek Kudüs'ü Haçlı işgalinden kurtaran ve III. Haçlı Seferi'nin başlamasına neden olan Türk-İslam hükümdarı aşağıdakilerden hangisidir?",
    "options": {
      "A": "Selahaddin Eyyubi",
      "B": "Nureddin Zengi",
      "C": "Baybars",
      "D": "Alparslan",
      "E": "Gazneli Mahmut"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Selahaddin Eyyubi\n1187 yılında yapılan Hıttin Savaşı ile Haçlı ordusunu ağır bir hezimete uğratarak 88 yıllık Haçlı işgaline son veren ve Kudüs'ü fetheden hükümdar Selahaddin Eyyubi'dir. Kudüs'ün fethi üzerine Avrupa'da kralların katıldığı III. Haçlı Seferi düzenlenmiştir. Kendisine \"Hâdimü'l-Haremeyn\" (Mekke ve Medine'nin Hizmetkârı) unvanı verilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Nureddin Zengi: Musul ve Halep Atabeyi olup Haçlılara karşı büyük mücadeleler vermiş, Selahaddin Eyyubi'yi yetiştirmiş büyük İslam komutanıdır.\n• C) Sultan Baybars: Memlük Devleti'nin en parlak hükümdarıdır; 1260 Ayn Calut Savaşı'nda Moğolları tarihte İLK kez durduran ve 1277 Elbistan Savaşı'nda yenen liderdir.\n• D) Alparslan: Büyük Selçuklu hükümdarıdır; 1071 Malazgirt Zaferi ile Anadolu'nun kapılarını Türklere açmıştır.\n• E) Gazneli Mahmut: Gazneli hükümdarıdır; Hindistan'a 17 sefer düzenleyerek İslamiyeti yaymış, ilk \"Sultan\" unvanlı hükümdardır.\n\n💡 KPSS HAFIZA KARTI:\nHâdimü'l-Haremeyn (Mekke ve Medine'nin Hizmetkârı) unvanını kullanan ilk hükümdar Selahaddin Eyyubi, Osmanlı'da kullanan ilk padişah ise Yavuz Sultan Selim'dir.",
