    "topic": "İlk Türk-İslam Devletleri Kültür ve Medeniyeti (Tasavvuf Öncüleri)",
    "questionText": "Türk-İslam tarihinde tasavvuf düşüncesinin gelişmesinde ve halk arasında yayılmasında etkili olan mutasavvıflar arasında aşağıdakilerden hangisi yer almaz?",
    "options": {
      "A": "Ahmet Yesevi",
      "B": "Mevlânâ Celaleddin-i Rumi",
      "C": "Hacı Bayrâm-ı Veli",
      "D": "Karacaoğlan",
      "E": "Ahi Evran"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Karacaoğlan\nKaracaoğlan, Türk-İslam tasavvuf akımının kurucu mutasavvıfı değil; XVII. yüzyılda (17. yy) yaşamış, din ve tasavvuftan ziyade beşeri aşkı, doğayı ve güzellemeleri işleyen saz şairi ve AŞIK EDEBİYATI temsilcisidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Ahmet Yesevi: XII. yüzyılda yaşamış \"Pir-i Türkistan\" olarak bilinen İLK büyük Türk mutasavvıfıdır. Eseri \"Divan-ı Hikmet\" ile Anadolu'nun İslamlaşmasına zemin hazırlamıştır.\n• B) Mevlânâ Celaleddin-i Rumi: XIII. yüzyılda Anadolu Selçuklu döneminde Konya'da yaşamış; Mesnevi, Divan-ı Kebir ve Fihi Ma Fih eserleriyle evrensel hoşgörünün simgesi olmuştur.\n• C) Hacı Bayrâm-ı Veli: XV. yüzyılda Ankara'da Bayramiye tarikatını kuran, II. Murat döneminde etkili olmuş mutasavvıf şairdir.\n• E) Ahi Evran: XIII. yüzyılda Kırşehir merkezli \"Ahilik Teşkilatı\"nı (esnaf dayanışma örgütünü) kuran mutasavvıftır; eseri Letaif-i Hikmet'tir. Eşi Fatma Bacı ise Bacıyan-ı Rum'u (Dünyanın ilk kadın teşkilatı) kurmuştur.\n\n💡 KPSS HAFIZA KARTI:\nAnadolu'nun Manevi Mimarları (Horasan Erenleri): Ahmet Yesevi öğrencileri -> Hacı Bektaş-ı Veli, Ahi Evran, Yunus Emre, Mevlânâ.",
