    "topic": "İlk Türk-İslam Devletleri Kültür ve Medeniyeti (Askeri Teşkilat)",
    "questionText": "İlk Türk-İslam devletlerinde savaş esirleri ve satın alma yoluyla temin edilen çocukların yetiştirilmesiyle oluşturulan askerî birliklere verilen isim aşağıdakilerden hangisidir?",
    "options": {
      "A": "Gulam",
      "B": "Pençik",
      "C": "Redif",
      "D": "Cebelü",
      "E": "Çeri"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Gulam\nİlk Türk-İslam devletlerinde (Karahanlılar, Gazneliler, Büyük Selçuklu) savaş esirleri ve satın alma yoluyla toplanan gayrimüslim çocukların sarayda özel eğitimden geçirilip asker veya bürokrat yapıldığı sisteme \"Gulam Sistemi\" denir. Saray muhafızlarına \"Gulamân-ı Saray\" denirdi. Bu sistem Osmanlı'daki \"Kapıkulu / Devşirme\" sisteminin temelidir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Pençik: Osmanlı Devleti'nde I. Murat döneminde uygulanan, savaş esirlerinin beşte birinin (1/5) devlet tarafından Yeniçeri Ocağı'na alınması sistemidir.\n• C) Redif: XIX. yüzyılda II. Mahmut döneminde Tımar sisteminin kalkmasıyla taşrada güvenliği sağlamak için kurulan yedek ordu teşkilatıdır.\n• D) Cebelü: İkta veya Tımar sahiplerinin gelirlerine karşılık devlete beslemek zorunda oldukları atlı zırhlı askerdir.\n• E) Çeri: Eski Türkçe'de ordu veya asker anlamına gelen genel tabirdir (\"yeniçeri\" de yeni asker demektir).\n\n💡 KPSS HAFIZA KARTI:\nOrdu Sistemleri Evrimi:\nSelçuklu'da Gulam = Osmanlı'da Kapıkulu / Devşirme\nSelçuklu'da İkta Askeri = Osmanlı'da Tımarlı Sipahi (Cebelü)",
