    "questionText": "751 yılında Müslüman Abbasiler ile Çinliler arasında yapılan, Karluk Türklerinin Abbasilerin yanında yer alarak Çin'in yenilgiye uğratıldığı ve Türk-İslam tarihinin başlangıcı sayılan savaş aşağıdakilerden hangisidir?",
