    "explanation": "✅ DOĞRU CEVAP: B) Talas Savaşı (751)\n751 yılında Müslüman Abbasi ordusu ile Çin ordusu arasında Orta Asya hakimiyeti için yapılan Talas Savaşı'nda (Atlantik Savaşı), Karluk Türkleri Abbasilerin safına geçmiş ve Çin hezimete uğramıştır. Bu savaşla Türkler kitleler halinde İslamiyet'e girmeye başlamış; kâğıt ilk kez Çin dışına (Semerkant'a) çıkarılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Miryokefalon Savaşı (1176): II. Kılıçarslan döneminde Bizans mağlup edilmiş, \"Anadolu'nun Türk yurdu olduğu kesinleşmiştir\" (Yurttutan Savaş).\n• C) Hudeybiye Barışı (628): Hz. Muhammed ile Mekkeli müşrikler arasında imzalanan, Mekkelilerin İslam devletini hukuken ilk kez tanıdığı antlaşmadır.\n• D) Margos Antlaşması (435): Avrupa Hun Devleti hükümdarı Attila'nın Bizans ile yaptığı, Bizans'ın vergisini iki katına çıkardığı antlaşmadır.\n• E) Pasinler Savaşı (1048): Büyük Selçuklu Devleti ile Bizans arasında yapılan İLK büyük savaştır.\n\n💡 KPSS HAFIZA KARTI:\n751 Talas Savaşı Önemi:\n1. Türk-İslam tarihinin başlangıcıdır.\n2. İlk Müslüman Türk boyu Karluklar olmuştur.\n3. Semerkant'a ilk kez kağıt atölyesi açılmış ve Semerkant \"Şehirlerin Şahı\" unvanını almıştır.",
