    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Atabeg (Atabey)\nSelçuklularda (Büyük Selçuklu ve Türkiye Selçukluları) şehzadelere \"Melik\" denirdi. Melikler eyaletlere yönetici olarak gönderildiğinde, yanlarına devlet idaresini, askeri stratejiyi ve teşkilatçılığı öğretmek üzere son derece tecrübeli devlet adamları olan \"Atabegler\" verilirdi.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Lala: Osmanlı Devleti'nde şehzadeleri yetiştiren eğitmenlere verilen addır (Atabey'in Osmanlı'daki karşılığı).\n• C) Vezir: Hükümdardan sonraki en yetkili idari görevlidir. Selçuklular'da hükümet başkanı Vezir-i Azam, Osmanlı'da Sadrazamdır.\n• D) Hâcip: Hükümdar ile divan üyeleri, halk ve elçiler arasındaki diplomatik ilişkileri düzenleyen saray protokol görevlisidir.\n• E) Sipahi: İkta veya tımar arazilerine bağlı olarak yetişen, barışta çiftçiyi ve güvenliği koruyan, savaşta orduya katılan atlı askerdir.\n\n💡 KPSS HAFIZA KARTI:\nŞehzade Eğitmenleri:\n• Selçuklu'da: Atabeg (Merkezi otorite bozulunca bağımsızlık ilan etmişlerdir).\n• Osmanlı'da: Lala (Merkezi otorite güçlü tutulduğu için bağımsız devlet kuramamışlardır).",
