    "markedAnswer": "D",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Farabi (El-Pharabius)\nİslam felsefesinin kurucusu kabul edilen Farabi, Aristo'nun (Muallim-i Evvel / Birinci Öğretmen) eserlerini şerh edip geliştirdiği için \"Muallim-i Sani\" (İkinci Öğretmen) unvanını almıştır. İlimleri ilk kez tasnif ettiği \"İhsâü'l-Ulûm\", ideal devleti anlattığı \"El-Medinetü'l Fazıla\" ve ilk modern müzik kitabı \"Kitabü'l Musiki\" onun başyapıtlarıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) İbn-i Sina (Avicenna): Tıbbın babası sayılır. \"El-Kanun fi't-Tıbb\" (Tıbbın Kanunu) ve \"Kitabü'ş-Şifa\" eserleri Avrupa üniversitelerinde asırlarca okutulmuştur; \"Şeyhü'r-Reis\" olarak anılır.\n• C) Biruni (Aliboron): Gazneli Mahmut'un \"Sarayımın en değerli hazinesi\" dediği bilim insanıdır. Dünya'nın çapını ve eksen eğikliğini hesaplamıştır (\"El-Asarü'l-Bakiye\").\n• D) İbn-i Rüşd (Averroes): Endülüs'te yaşamış, Aristo'yu Batı'ya tanıtan büyük akılcı filozoftur; Avrupalılar ona \"Büyük Yorumcu\" (Commentator) demiştir.\n• E) İmam Gazali: Büyük Selçuklu döneminde Nizamiye Medreseleri'nin başmüderrisliğini yapmış; \"İhyâu Ulûmi'd-Dîn\" ve felsefecileri eleştirdiği \"Tehâfütü'l-Felâsife\" eserlerini yazmıştır.\n\n💡 KPSS HAFIZA KARTI:\nİslam Bilginleri Kodlamaları:\n• Muallim-i Sani = Farabi\n• Şeyhü'r-Reis = İbn-i Sina\n• Sarayımın Hazinesi = Biruni\n• Aristo Yorumcusu (Endülüs) = İbn-i Rüşd",
    "isMapQuestion": false,
    "file": "20260905_000657.jpg"
