    "explanation": "✅ DOĞRU CEVAP: C) III (Artuklular - Karaman)\nArtuklular Karaman'da değil; Güneydoğu Anadolu'da (Mardin, Hasankeyf/Batman, Harput/Elazığ ve Diyarbakır) kurulmuştur. Karaman merkezli kurulan beylik ise II. Dönem Türk beyliği olan ve Türkçe'yi resmi dil ilan eden Karamanoğullarıdır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) I. Mengücekliler - Erzincan: Doğrudur. Erzincan, Kemah, Divriği çevresinde kurulmuştur; Divriği Ulu Camii ve Darüşşifası UNESCO Dünya Mirası kalıcı listesindedir.\n• B) II. Danişmentliler - Sivas: Doğrudur. Sivas, Tokat, Niksar çevresinde kurulmuş ve Yağıbasan Medresesi'ni inşa etmişlerdir.\n• D) IV. Saltuklular - Erzurum: Doğrudur. Erzurum ve Kars çevresinde kurulan İLK Türk beyliğidir; Mama Hatun Kümbeti ve Üç Kümbetler'i bırakmışlardır.\n• E) V. Çaka Beyliği - İzmir: Doğrudur. 1081'de ilk Türk donanmasını kuran Çaka Bey tarafından İzmir ve çevresinde kurulmuştur.\n\n💡 KPSS HAFIZA KARTI:\n1081 yılı (Çaka Beyliği'nin kuruluşu), Türk Deniz Kuvvetleri'nin resmî kuruluş yılı kabul edilir!",
