    "topic": "Türk-İslam Tarihi",
    "questionText": "Bizans İmparatoru Romen Diyojen’in, Büyük Selçuklu Sultanı Alparslan’ın barış teklifini reddederek sefere çıkması ve ardından yapılan muharebede Selçuklulara esir düşmesi aşağıdaki savaşlardan hangisinde gerçekleşmiştir?",
    "options": {
      "A": "Pasinler Savaşı",
      "B": "Malazgirt Savaşı",
      "C": "Miryokefalon Savaşı",
      "D": "Katvan Savaşı",
      "E": "Dandanakan Savaşı"
    },
    "markedAnswer": "A",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Malazgirt Savaşı (26 Ağustos 1071)\n1071 Malazgirt Meydan Muharebesi'nde Büyük Selçuklu Sultanı Alparslan, Bizans İmparatoru Romen Diyojen'i mağlup ederek esir almıştır. Bu zaferle Anadolu'nun kapıları Türklere tamamen açılmış ve I. Dönem Anadolu Türk Beylikleri kurulmaya başlamıştır (Yurtiçeren/Yurkaçan Savaş).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Pasinler Savaşı (1048): Tuğrul Bey döneminde İbrahim Yinal komutasındaki Selçuklular ile Bizans ve Gürcü ittifakı (Liparid) arasında yapılan İLK savaştır; keşif ve yıpratma savaşıdır.\n• C) Miryokefalon Savaşı (1176): Anadolu Selçuklu Sultanı II. Kılıçarslan'ın Bizans'ı hezimete uğrattığı ve Anadolu'nun Türk yurdu olduğunu tescilleyen savaştır (Yurttutan Savaş).\n• D) Katvan Savaşı (1141): Büyük Selçuklu Sultanı Sencer'in Moğol kökenli Karahitaylara yenildiği ve devletin yıkılış sürecine girdiği savaştır.\n• E) Dandanakan Savaşı (1040): Tuğrul ve Çağrı Beylerin Gazneli Mesut'u mağlup ederek Büyük Selçuklu Devleti'ni resmen kurdukları savaştır.\n\n💡 KPSS HAFIZA KARTI:\nAnadolu'nun Tapu Aşamaları:\n1. Pasinler (1048) = Keşif ve Kapıyı çalma\n2. Malazgirt (1071) = Kapıyı açma (Yurtaçan)\n3. Miryokefalon (1176) = Tapuyu alma / Kesinleştirme (Yurttutan)\n4. Kurtuluş Savaşı / Büyük Taarruz (1922) = Yurtkurtaran",
    "isMapQuestion": false,
