    "questionText": "1071 yılında yapılan Malazgirt Savaşı'ndan sonra Kemah, Erzincan, Divriği bölgelerinde kurulan ve Trabzon Rum İmparatorluğu'nun güneye inmesine engel olan beylik (devlet) aşağıdakilerden hangisidir?",
