    "questionText": "5. • İzmir ve çevresinde kurulmuş ve denizcilikle uğraşmışlardır.\n• Gürcüler ve Rumlarla çatışmalar yaşamış ve Divriği Ulu Camisi'ni inşa etmişlerdir.\n• Anadolu'da kurulan ilk Türk beyliği olup Erzurum'u merkez edinmiş ve Mama Hatun Külliyesi'ni inşa etmişlerdir.\n• Hasankeyf, Mardin ve Harput merkezli üç kol halinde yaşamış, Diyarbakır'daki Malabadi Köprüsü'nü yapmışlardır.\nBu açıklamalarda aşağıdaki Türk beyliklerinden hangisiyle ilgili bilgi verilmemiştir?",
