    "explanation": "✅ DOĞRU CEVAP: C) Danişmentliler\nSoru öncüllerinde verilen özellikler şöyledir:\n• İzmir ve denizcilik -> Çaka Beyliği (D)\n• Gürcüler ve Rumlarla çatışma, Erzurum, Mama Hatun Kümbeti -> Saltuklular (E)\n• Divriği Ulu Camii, Erzincan ve Kemah -> Mengücekliler (B)\n• Malabadi Köprüsü, Mardin ve Batman -> Artuklular (A)\nÖncüllerde Danişmentliler ile ilgili bilgi (Sivas, Tokat, Niksar, Yağıbasan Medresesi) yer almaz!\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Artuklular: Mardin, Hasankeyf, Harput'ta kurulmuş; Malabadi Köprüsü ve ünlü bilim insanı El-Cezeri ile tanınırlar.\n• B) Mengücekliler: Erzincan-Divriği'de kurulmuş; Divriği Ulu Camii ve Darüşşifası'nı yapmışlardır.\n• D) Çaka Beyliği: İzmir'de ilk Türk donanmasını kuran denizci beyliktir.\n• E) Saltuklular: Erzurum'da kurulmuş; Mama Hatun Külliyesi ve Üç Kümbetler'i inşa etmişlerdir.\n\n💡 KPSS HAFIZA KARTI:\nI. Dönem Türk Beyliklerinin Anadolu'ya En Büyük Hizmeti: Anadolu'yu Haçlılara, Bizans'a ve Gürcülere karşı koruyup bayındır hale getirerek kalıcı Türk yurdu yapmalarıdır.",
