    "topic": "Osmanlı Kuruluş Dönemi / I. Murat Savaşları",
    "questionText": "7. Bitirme tezi için, Çirmen, Sırpsındığı ve I. Kosova savaşları ile Osmanlı'nın ilk savaş toplarını inceleyen bir öğretim görevlisi, aşağıdaki Osmanlı hükümdarlarından hangisinin dönemini araştırmaktadır?",
    "options": {
      "A": "I. Murat",
      "B": "Orhan Bey",
      "C": "I. Bayezid",
      "D": "II. Murat",
      "E": "Osman Bey"
    },
    "markedAnswer": "C",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) I. Murat (Hüdavendigar)\nI. Murat (1362-1389) saltanatında;\n• Sırpsındığı Savaşı (1364): Haçlılara karşı kazanılan İLK Osmanlı zaferidir.\n• Çirmen Savaşı (1371): Sırplar mağlup edilmiş, Makedonya'nın fethi kolaylaşmıştır.\n• I. Kosova Savaşı (1389): Büyük Haçlı ordusu mağlup edilmiş, Osmanlı tarihinde İLK kez ses ve korkutma amacıyla savaş topu kullanılmıştır. (I. Murat savaş meydanını gezerken Sırp Miloş Obiliç tarafından şehit edilmiştir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Orhan Bey: Bursa'yı fethedip başkent yapan, Karesioğulları'nı alıp ilk donanmayı kuran, Rumeli'ye (Çimpe Kalesi) ilk geçen padişahtır.\n• C) I. Bayezid (Yıldırım): Niğbolu Zaferi (1396) ile \"Sultan-ı İklim-i Rum\" unvanını alan, Anadolu Türk siyasi birliğini ilk kez geniş ölçüde sağlayan hükümdardır.\n• D) II. Murat: Varna (1444) ve II. Kosova (1448) zaferleriyle Haçlıları püskürten, \"Koca Murat\" ve \"Hayır Babası\" olarak anılan padişahtır.\n• E) Osman Bey: Koyunhisar (Bafeus - 1302) Savaşı'nda Bizans tekfurlarını yenen ve devleti bağımsız hale getiren kurucu hükümdardır.\n\n💡 KPSS HAFIZA KARTI:\nSavaş Meydanında Şehit Düşen TEK Osmanlı Padişahı: I. Murat (Hüdavendigar) - 1389 I. Kosova Savaşı.",
