    "topic": "Osmanlı Tarihi / Lale Devri ve Islahatlar",
    "questionText": "Lale Devri'nde Paris'e geçici elçi olarak gönderilen ve gördüklerini \"Sefaretname\" adlı eserinde toplayarak Osmanlı'da Batılılaşma hareketlerine öncülük eden devlet adamı aşağıdakilerden hangisidir?",
    "options": {
      "A": "Yirmisekiz Mehmet Çelebi",
      "B": "Yusuf Agâh Efendi",
      "C": "Ahmet Resmi Efendi",
      "D": "Ebubekir Ratıp Efendi",
      "E": "İbrahim Müteferrika"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yirmisekiz Mehmet Çelebi\n1718-1730 Lale Devri'nde (III. Ahmet ve Nevşehirli Damat İbrahim Paşa dönemi), 1720 yılında Paris'e \"geçici elçi\" olarak gönderilen ve Fransa'daki askeri, mimari, sanatsal ve teknolojik gelişmeleri \"Paris Sefaretnamesi\" eserinde toplayarak Osmanlı modernleşmesine yön veren Osmanlı devlet adamıdır. Oğlu Said Efendi ile birlikte İbrahim Müteferrika'nın ilk matbaayı açmasına destek olmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Yusuf Agâh Efendi: III. Selim döneminde (1793) İngiltere'ye (Londra) gönderilen İLK DAİMİ Osmanlı elçisidir.\n• C) Ahmet Resmi Efendi: XVIII. yüzyılda Viyana ve Berlin'e elçi olarak gönderilen ve buralardaki gözlemlerini sefaretnameye döken diplomattır.\n• D) Ebubekir Ratıp Efendi: III. Selim tarafından Viyana'ya gönderilen ve Nizam-ı Cedid ıslahatlarının fikir altyapısını oluşturan büyük raporu (Layihayı) hazırlayan diplomattır.\n• E) İbrahim Müteferrika: Macar asıllı olup Lale Devri'nde (1727) Osmanlı'daki İLK Türk/Müslüman matbaasını kuran ve ilk olarak Vankulu Lugatı'nı basan fikir insanıdır.\n\n💡 KPSS HAFIZA KARTI:\nElçiler Kronolojisi:\n• İlk Geçici Elçi: Yirmisekiz Mehmet Çelebi (Paris / Lale Devri)\n• İlk Daimi Elçi: Yusuf Agâh Efendi (Londra / III. Selim)",
