    "topic": "Osmanlı Tarihi (Kuruluş Dönemi / Ordu Teşkilatı)",
    "questionText": "Osmanlı Devleti'nin ilk düzenli askeri teşkilatı aşağıdakilerden hangisidir?",
    "options": {
      "A": "Yaya ve Müsellemler",
      "B": "Akıncılar",
      "C": "Cebeci Ocağı",
      "D": "Deliler ve Azaplar",
      "E": "Sipahiler"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Yaya ve Müsellemler\nOsmanlı Devleti'nin kuruluşunun ilk yıllarında ordu, aşiret süvarileri ve gazilerden oluşuyordu. Bursa'nın fethi sırasında düzenli bir ordunun eksikliği hissedilince **Orhan Bey** döneminde Vezir Çandarlı Halil Paşa ve Bursa Kadısı Alaeddin Paşa'nın önerisiyle Türk gençlerinden oluşan tarihteki İLK DÜZENLİ ORDU: **Yaya (piyade) ve Müsellem (atlı süvari)** teşkilatı kurulmuştur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Akıncılar: Sınırlarda düşman topraklarına keşif ve yıpratma akınları düzenleyen, hafif atlı öncü birliklerdir (Malkoçoğulları, Turahanoğulları vb.).\n• C) Cebeci Ocağı: Kapıkulu ordusunun silahlarını temin eden, tamir eden ve cephaneyi koruyan teknik askeri sınıftır.\n• D) Deliler ve Azaplar: Deliler sınırda korkusuzca savaşan atlı birliklerdir; Azaplar ise ordunun en önünde yer alan bekar Türk gençlerinden oluşan gönüllü piyadelerdir.\n• E) Sipahiler: Tımar gelirleriyle beslenen atlı eyalet askerleridir.\n\n💡 KPSS HAFIZA KARTI:\nOsmanlı Ordu Aşamaları:\n1. Gönüllü Alpler ve Gaziler (Osman Bey)\n2. İlk Düzenli Ordu: Yaya ve Müsellem (Orhan Bey)\n3. Kapıkulu (Yeniçeri) Ocağı: I. Murat (Pençik sistemi ile)",
    "isMapQuestion": false,
