    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Vasvar Antlaşması (1664)\nVasvar Antlaşması (1664), Safevi (İran) Devleti ile değil; **Avusturya** ile imzalanmıştır. Köprülü Fazıl Ahmet Paşa'nın Uyvar Kalesi'ni fethi üzerine (\"Uyvar önünde bir Türk gibi güçlü\" deyimi) imzalanmış ve Avusturya Osmanlı'ya son kez savaş tazminatı ödemiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Ferhat Paşa Antlaşması (1590): III. Murat döneminde İran ile yapılmış, Osmanlı'nın DOĞUDA EN GENİŞ SINIRLARA ulaştığı antlaşmadır.\n• C) Kasr-ı Şirin Antlaşması (1639): IV. Murat döneminde İran ile yapılmış, bugünkü TÜRKİYE - İRAN SINIRINI büyük oranda belirleyen tarihi antlaşmadır (Zağros Dağları sınır oldu).\n• D) Serav Antlaşması (1618): II. Osman (Genç Osman) döneminde İran ile yapılmış, Nasuh Paşa vergisinin yarıya indirildiği antlaşmadır.\n• E) Amasya Antlaşması (1555): Kanuni Sultan Süleyman döneminde imzalanan, Osmanlı ile Safeviler (İran) arasındaki İLK RESMÎ BARIŞ ANTLAŞMASIDIR.\n\n💡 KPSS HAFIZA KARTI:\nİran ile Yapılan Antlaşmalar Şifresi: **FANSEK**\n• **F**erhat Paşa (Doğuda en geniş sınır)\n• **A**masya (İlk resmi antlaşma - 1555)\n• **N**asuh Paşa (Taviz verildi)\n• **S**erav (Vergi indi)\n• **K**asr-ı Şirin (Günümüz sınırları)",
    "isMapQuestion": false,
