    "questionText": "Yıldırım Beyazıt’ın 1391 - 1401 yılları arasında üstüstte yaptığı İstanbul kuşatmalarını kaldırmasında\n\nI. Niğbolu Savaşı’nın başlaması,\nII. doğuda Timur tehlikesinin görülmesi,\nIII. Osmanlı akıncılarının Ploşnik’te pusuya düşürülmesi\n\ngelişmelerinden hangileri etkili olmuştur?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız II",
      "C": "I ve II",
      "D": "I ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "E",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) I ve II (Niğbolu Savaşı ve Timur Tehlikesi)\nYıldırım Bayezid (I. Bayezid), İstanbul'u 4 kez kuşatmış (ve Anadolu Hisarı'nı yaptırmış) ancak kuşatmaları iki büyük dış tehdit nedeniyle kaldırmak zorunda kalmıştır:\n1. 1396'da büyük Haçlı ordusunun Tuna boylarında Niğbolu Kalesi'ni kuşatması üzerine orduyla Batı'ya gitmiş ve Niğbolu Zaferi'ni kazanmıştır (I).\n2. 1401-1402'de doğudan gelen Timur tehlikesi ve Sivas'ın Timur ordusunca tahrip edilmesi üzerine kuşatmayı kaldırıp Ankara'ya yürümüştür (II).\nPloşnik Bozgunu ise (III) 1388'de babası I. Murat döneminde yaşanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Niğbolu Savaşı (1396): Haçlıların Bulgaristan'da imha edildiği savaştır; Abbasi Halifesi I. Bayezid'e \"Sultan-ı İklim-i Rum\" (Anadolu Diyarının Sultanı) unvanını vermiştir.\n• II. Timur Tehlikesi: 1402 Ankara Savaşı'na ve Osmanlı'nın 11 yıl sürecek Fetret Devri'ne girmesine yol açmıştır.\n• III. Ploşnik Bozgunu (1388): Sırp ve Boşnak kuvvetlerinin Osmanlı öncü akıncılarını pusuya düşürdüğü yenilgidir; I. Kosova Savaşı'na zemin hazırlamıştır.\n\n💡 KPSS HAFIZA KARTI:\nİstanbul Kuşatmaları:\n• İslam tarihinde ilk kuşatan: Muaviye / Emeviler (Eyüp El Ensari şehit düştü)\n• Türk tarihinde ilk kuşatan: Avarlar\n• Osmanlı'da ilk kuşatan: Yıldırım Bayezid (Güzelcehisar / Anadolu Hisarı'nı yaptırdı).",
