    "explanation": "✅ DOĞRU CEVAP: B) II. Mahmut\nOsmanlı Devleti'nde Batı tarzı modern devlet bürokrasisi, tıp ve subay kadrosu yetiştirmek amacıyla Avrupa'ya (özellikle Paris, Londra ve Viyana'ya) İLK KEZ resmî öğrenci gönderen padişah **II. Mahmut**tur. Bu öğrenciler daha sonra Tanzimat Fermanı'nı ilan eden ve \"Genç Osmanlılar / Jön Türkler\" hareketini başlatan aydın kadroyu oluşturmuşlardır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) III. Selim: Avrupa'ya öğrenci değil, Batı'daki gelişmeleri yerinde takip etmek için ilk \"daimi elçileri\" (Londra) göndermiştir.\n• C) II. Abdülhamit: I. Meşrutiyet (1876) ve II. Meşrutiyet'i (1908) ilan eden, Sanayi-i Nefise Mektebi ve Darülaceze'yi açan padişahtır.\n• D) Sultan Abdülmecit: Tanzimat (1839) ve Islahat (1856) fermanlarını ilan eden, ilk demiryolu ve ilk telgraf hattını kuran padişahtır.\n• E) Sultan Abdülaziz: Osmanlı tarihinde barış zamanında **Avrupa seyahatine çıkan İLK ve TEK padişahtır** (Paris, Londra, Viyana).\n\n💡 KPSS HAFIZA KARTI:\nAvrupa ile İlişkilerde Padişah İlkleri:\n• İlk Geçici Elçi Gönderen: III. Ahmet (Lale Devri)\n• İlk Daimi Elçi Gönderen: III. Selim\n• İlk Öğrenci Gönderen: II. Mahmut\n• Avrupa'ya Bizzat Seyahate Giden İlk Padişah: Sultan Abdülaziz",
