    "category": "Osmanlı Devleti — Kültür ve Medeniyet",
    "topic": "Osmanlı Kültür ve Medeniyeti / XIX. Yüzyıl Eğitim Kurumları",
    "questionText": "12. Aşağıdakilerden hangisi Osmanlı Devleti'nin XIX. yüzyılında açılan modern eğitim kurumlarından birisi değildir?",
    "options": {
      "A": "Mekteb-i Tıbbiye",
      "B": "Dârü'l Muallimin",
      "C": "Mekteb-i Harbiye",
      "D": "Tüfekhane",
      "E": "Sanayi-i Nefise Mektebi"
    },
    "markedAnswer": "C",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Tüfekhane\nTüfekhane bir eğitim kurumu değil; ordunun tüfek, süngü ve hafif ateşli silahlarının imal edildiği, bakımının ve onarımının yapıldığı askeri bir fabrikadır (imalathanedir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Mekteb-i Tıbbiye: II. Mahmut döneminde (1827) modern tıp eğitimi ve askeri cerrah yetiştirmek amacıyla açılan ilk tıp fakültesidir.\n• B) Dârü'l-Muallimin: Tanzimat döneminde (1848) rüştiyelere modern erkek öğretmen yetiştirmek amacıyla açılan ilk öğretmen okuludur.\n• C) Mekteb-i Harbiye: II. Mahmut döneminde (1834) modern subay ve kurmay yetiştirmek için kurulan Harp Okulu'dur.\n• E) Sanayi-i Nefise Mektebi: II. Abdülhamit döneminde (1882) Osman Hamdi Bey öncülüğünde açılan ilk Güzel Sanatlar Akademisi'dir (bugünkü Mimar Sinan Güzel Sanatlar Üniversitesi).\n\n💡 KPSS HAFIZA KARTI:\nXIX. Yüzyıl Okulları:\n• Mekteb-i Tıbbiye & Harbiye: II. Mahmut\n• Dârü'l-Muallimin (Erkek Öğretmen): Abdülmecit\n• Dârü'l-Muallimat (Kız Öğretmen): Abdülaziz\n• Mülkiye Mektebi: Abdülmecit\n• Sanayi-i Nefise Mektebi: II. Abdülhamit (Osman Hamdi Bey).",
    "isMapQuestion": false,
