    "explanation": "✅ DOĞRU CEVAP: B) Hukukta birliğin bulunmadığının\nBir ülkede aynı anda farklı toplumsal kesimler için farklı hukuk kurallarının ve ayrı mahkemelerin (Müslümanlar için Şer'i Mahkemeler, Hristiyan/Museviler için Cemaat Mahkemeleri, Avrupalılar için Konsolosluk Mahkemeleri, 19. yy'da karma Ticaret/Nizamiye Mahkemeleri) bulunması, o ülkede **Hukuk Birliğinin ve Hukuk Eşitliğinin Bulunmadığının** en net göstergesidir. Bu ikilik Cumhuriyet döneminde Medeni Kanun ile kaldırılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Laik hukuk sistemi: Osmanlı hukuku şeriata dayalıdır, laik değildir.\n• C) Merkeziyetçi yönetimin güçlenmesi: Aksine farklı mahkemelerin varlığı merkezi otoriteyi zaafa uğratmış, yabancı devletlerin iç işlerimize karışmasına zemin hazırlamıştır.\n• D) Tüm vatandaşların eşit haklara sahip olması: Farklı mahkemelerin olması eşitliğin olmadığının kanıtıdır.\n• E) Yargı bağımsızlığı: Yabancı konsolosların kendi vatandaşlarını yargılaması kapitülasyonların getirdiği bir yargı imtiyazıdır, bağımsızlık değildir.\n\n💡 KPSS HAFIZA KARTI:\nHukukta Birliğin Sağlanması:\n1926 Türk Medeni Kanunu'nun kabulü ve Şer'iye Mahkemelerinin kapatılması ile Türkiye'de hukuk birliği kesin olarak sağlanmıştır.",
