    "topic": "Kurtuluş Savaşı Hazırlık Dönemi / Raporlar ve Cemiyetler",
    "questionText": "Milli Mücadele Dönemi'nde ABD Başkanı Wilson'un talimatıyla Anadolu'ya gönderilen ve hazırladığı raporda Ermeni iddialarının asılsız olduğunu, bölgede Türk nüfusunun çoğunlukta bulunduğunu belirterek \"Yakın Doğu Hakikatleri\" başlığıyla yayımlanan rapor aşağıdakilerden hangisidir?",
    "options": {
      "A": "Amiral Bristol Raporu",
      "B": "General Harbord Raporu",
      "C": "King-Crane Raporu",
      "D": "Milne Hattı Raporu",
      "E": "Sandler Raporu"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) General Harbord Raporu\nMilli Mücadele Dönemi'nde ABD Başkanı Woodrow Wilson'ın talimatıyla bölgeye gönderilen General James Harbord başkanlığındaki Amerikan heyeti; Doğu Anadolu ve Kafkasya'da aylarca inceleme yapmış ve Sivas'ta Mustafa Kemal ile görüşmüştür. Hazırladığı raporda; **\"Doğu Anadolu'da Türklerin çoğunlukta olduğunu, Ermenilerin iddialarının asılsız olduğunu ve bir Amerikan mandasının gereksiz olduğunu\"** bildirmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Amiral Bristol Raporu: İzmir ve Batı Anadolu'da Rum iddialarının asılsız olduğunu, katliamları Yunanlıların yaptığını ve Türklerin çoğunlukta olduğunu belirten İLK uluslararası belgedir.\n• C) King-Crane Raporu: I. Dünya Savaşı sonrasında Suriye ve Filistin bölgesinde manda yönetimi üzerine hazırlanan Amerikan raporudur.\n• D) Milne Hattı Raporu: İngiliz General Milne tarafından Batı Anadolu'da Türk kuvvetleri ile Yunan işgal kuvvetleri arasına çizilen yapay sınır hattıdır.\n• E) Sandler Raporu: 1936'da Milletler Cemiyeti tarafından Hatay sorununun çözümü için hazırlanan ve Hatay'ın bağımsızlığına zemin hazırlayan rapordur.\n\n💡 KPSS HAFIZA KARTI:\nMilli Mücadele'nin Haklılığını Tescilleyen Uluslararası Raporlar:\n• Batı Cephesi / Rum İddialarına Karşı: **Amiral Bristol Raporu** (İlk rapor)\n• Doğu Cephesi / Ermeni İddialarına Karşı: **General Harbord Raporu**",
    "isMapQuestion": false,
