    "topic": "Avrupa Tarihi / XIX. Yüzyıl Diplomasisi",
    "questionText": "Bismarck önderliğinde XIX. yüzyılda kurulan ve birkaç kez yenilenmek durumunda kalınan “Üç İmparatorlar Ligi”ni oluşturan devletler aşağıdakilerin hangisinde doğru olarak verilmiştir?",
    "options": {
      "A": "Almanya - Rusya - Fransa",
      "B": "Fransa - İngiltere - Almanya",
      "C": "Almanya - Avusturya-Macaristan - Rusya",
      "D": "İngiltere - Avusturya-Macaristan - Almanya",
      "E": "Rusya - Almanya - İtalya"
    },
    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Almanya - Avusturya-Macaristan - Rusya\n1871'de siyasi birliğini tamamlayan Almanya Şansölyesi Otto von Bismarck, Fransa'yı Avrupa'da tamamen yalnız bırakmak ve iki cepheli bir savaşı önlemek amacıyla 1873 yılında monarşik üç büyük imparatorluğu bir araya getiren **\"Üç İmparatorlar Ligi (Dreikaiserbund)\"**ni kurmuştur:\n1. **Almanya İmparatorluğu (I. Wilhelm)**\n2. **Avusturya-Macaristan İmparatorluğu (Franz Joseph)**\n3. **Rusya İmparatorluğu (II. Aleksandr)**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• Rusya ile Avusturya'nın Balkanlar üzerindeki çıkar çatışması (Panslavizm vs. Balkan yayılmacılığı) yüzünden bu birlik daha sonra çökmüş, Rusya Fransa ile ittifak kurmuştur.\n• İlerleyen süreçte Almanya, Avusturya ve İtalya \"Üçlü İttifak\"ı (1882); İngiltere, Fransa ve Rusya ise \"Üçlü İtilaf\"ı (1907) oluşturmuştur.\n\n💡 KPSS HAFIZA KARTI:\nI. Dünya Savaşı Öncesi Bloklaşma:\n• Üçlü İttifak (1882): Almanya, Avusturya-Macaristan, İtalya (sonra taraf değiştirdi).\n• Üçlü İtilaf (1907): İngiltere, Fransa, Rusya.",
