    "topic": "Çağdaş Türk ve Dünya Tarihi / Türk Dünyası",
    "questionText": "SSCB'nin dağılmasıyla birlikte bu birliğin içinde yer alan 15 devlet bağımsız olmuştur. Bağımsız olan bu devletlerden bazıları da Türk cumhuriyetleridir.\n\nBuna göre aşağıdakilerden hangisi SSCB'nin dağılmasıyla bağımsız olan Türk devletleri arasında değildir?",
    "options": {
      "A": "Özbekistan",
      "B": "Tacikistan",
      "C": "Türkmenistan",
      "D": "Kırgızistan",
      "E": "Kazakistan"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Tacikistan\n1991 yılında Sovyetler Birliği'nin (SSCB) dağılmasıyla bağımsızlığına kavuşan 5 bağımsız Türk devleti: **Azerbaycan, Kazakistan, Kırgızistan, Özbekistan ve Türkmenistan**dır. **Tacikistan** ise etnik olarak Fars (İran) kökenlidir, dili Farsça'nın bir lehçesi olan Tacikçedir ve Türk soylu bir cumhuriyet değildir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Özbekistan: Başkenti Taşkent'tir; Semerkant ve Buhara gibi tarihi medeniyet merkezlerine ev sahipliği yapar. İlk cumhurbaşkanı İslam Kerimov'dur.\n• C) Türkmenistan: Başkenti Aşkabat'tır; zengin doğalgaz yataklarına sahiptir, \"Daimi Tarafsızlık\" statüsünü benimsemiştir. İlk cumhurbaşkanı Saparmurat Niyazov'dur (Türkmenbaşı).\n• D) Kırgızistan: Başkenti Bişkek'tir; Tanrı Dağları eteklerinde kuruludur, Manas Destanı'nın vatanıdır. İlk cumhurbaşkanı Askar Akayev'dir.\n• E) Kazakistan: Yüzölçümü olarak en büyük Türk devletidir; Semey nükleer deneme sahasını kapatarak nükleerden gönüllü vazgeçen ilk devlettir. Kurucu lideri Nursultan Nazarbayev'dir.\n\n💡 KPSS HAFIZA KARTI:\nTürkiye, 1991'de SSCB'den ayrılan Türk cumhuriyetlerinin bağımsızlığını dünyada İLK TANIYAN DEVLET olmuştur (İlk tanıdığı ülke ise Azerbaycan'dır).",
    "isMapQuestion": false,
    "file": "20260905_000215.jpg"
