    "subjectNumber": 104,
    "categoryOrder": 7,
    "category": "Osmanlı Devleti — Dağılma Dönemi ve XIX. Yüzyıl Islahatları",
    "topic": "XX. Yüzyıl Başlarında Osmanlı Devleti (Mustafa Kemal'in Hayatı ve Öğrenim Dönemi)",
    "questionText": "Mustafa Kemal, aşağıdaki okullardan hangisinde eğitim aldığı sırada Osmanlı-Yunan savaşı çıkmış ve Osmanlı Devleti bu savaştan galip çıkmıştır?",
    "options": {
      "A": "Harp Akademisi",
      "B": "Harp Okulu",
      "C": "Manastır Askeri İdadisi",
      "D": "Selanik Askeri Rüştiyesi",
      "E": "Şemsi Efendi Mektebi"
    },
    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Manastır Askeri İdadisi\n1897 Osmanlı-Yunan Savaşı (Dömeke Meydan Muharebesi) çıktığında Mustafa Kemal, Makedonya'daki **Manastır Askeri İdadisi**'nde (Lise) 2. sınıf öğrencisiydi. Vatan sevgisi ve heyecanla okuldan kaçıp orduya gönüllü katılmak istemiş, ancak yaşı küçük olduğu için yakalanıp okula geri gönderilmiştir. Mustafa Kemal hatıralarında \"Gençliğimin en heyecanlı günleriydi, bu savaşa katılmayı çok istemiştim\" demiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Harp Akademisi (İstanbul): Mustafa Kemal'in 1905'te \"Kurmay Yüzbaşı\" olarak mezun olduğu en üst askeri okuludur.\n• B) Harp Okulu (İstanbul / Pangaltı): Mustafa Kemal'in 1902'de \"Teğmen\" rütbesiyle bitirdiği okuldur.\n• D) Selanik Askeri Rüştiyesi: Matematik öğretmeni Yüzbaşı Mustafa Bey'in kendisine \"Kemal\" adını verdiği ortaokuldur.\n• E) Şemsi Efendi Mektebi: Mustafa Kemal'in Selanik'te modern eğitim gördüğü ilk ilkokuldur.\n\n💡 KPSS HAFIZA KARTI:\nMustafa Kemal'in Eğitim Sıralaması:\n1. Mahalle Mektebi (Geleneksel)\n2. Şemsi Efendi Mektebi (Modern ilk)\n3. Selanik Mülkiye Rüştiyesi (Sivil ortaokul - Yarıda bıraktı)\n4. Selanik Askeri Rüştiyesi (\"Kemal\" adı eklendi)\n5. Manastır Askeri İdadisi (Tarih ve edebiyat bilinci - Ömer Naci & Dömeke Savaşı)\n6. İstanbul Harp Okulu (Teğmen)\n7. İstanbul Harp Akademisi (Kurmay Yüzbaşı).",
