    "markedAnswer": "A",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Kavalalı Mehmet Ali Paşa\n1798'de Napolyon'un Mısır'ı işgali üzerine Mısır'a giden ve Fransızların çekilmesinin ardından otorite kurarak 1805'te Mısır Valisi olan Kavalalı Mehmet Ali Paşa; Mısır'da Fransız subaylarla modern ordu ve donanma kurmuş, pamuk ziraatini geliştirmiş, fabrikalar ve kanallar açarak Mısır'ı adeta bağımsız modern bir devlete dönüştürmüştür. Bu nedenle tarihte **\"Modern Mısır'ın Kurucusu\"** ve **\"Doğu'nun Yıldızı\"** olarak anılır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Tepedelenli Ali Paşa: Yanya Valisi olup bağımsız hareket ettiği için II. Mahmut tarafından ortadan kaldırılan, isyanı sırasında Yunan ayaklanmasının patlak vermesine yol açan ayandır.\n• B) Cezzar Ahmet Paşa: 1799'da Akka Kalesi önünde 80 küsur yaşındayken Nizam-ı Cedid ordusuyla Napolyon'u hezimete uğratan Şam ve Sayda valisidir.\n• D) Alemdar Mustafa Paşa: Rusçuk ayanı olup II. Mahmut'u tahta çıkaran ve Sened-i İttifak'ı imzalatan güçlü sadrazamdır.\n• E) Ahmet Muhtar Paşa: 93 Harbi'nde Kafkas cephesinde Rusları durduran ve \"Gazi\" unvanı alan büyük Osmanlı komutanıdır.\n\n💡 KPSS HAFIZA KARTI:\nKavalalı İsyanı Sonucunda Doğan Krizler:\n• 1833 Kütahya Antlaşması (Kavalalı'ya Suriye ve Girit valilikleri de verildi)\n• 1833 Hünkar İskelesi Antlaşması (Rusya ile Boğazlar sorunu başladı)\n• 1838 Balta Limanı Ticaret Sözleşmesi (İngiliz desteği için imzalandı, ekonomi çöktü)\n• 1840 Londra Konferansı (Mısır meselesi uluslararası çözüme kavuştu).",
    "isMapQuestion": false,
    "file": "20260905_000921.jpg"
