    "questionText": "27. II. Dünya Savaşı'ndan sonra büyük devletlerin sömürgesi altındaki ülkeler teker teker bağımsızlıklarını ilan etmeye başlamıştır. Böylece 1945'ten itibaren dünyadaki bağımsız devlet sayısı artmıştır.\n\nBuna göre aşağıdakilerden hangisi bu süreçte bağımsız olan devletlerden birisi değildir?",
    "options": {
      "A": "Hindistan",
      "B": "Tunus",
      "C": "Yugoslavya",
      "D": "Güney Kore",
      "E": "Pakistan"
    },
    "markedAnswer": "B",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) Yugoslavya\nYugoslavya (Güney Slavları Krallığı), II. Dünya Savaşı sonrasında sömürgecilikten kurtularak bağımsız olmuş bir devlet DEĞİLDİR; **I. Dünya Savaşı'ndan sonra (1918'de)** Sırp, Hırvat ve Sloven Krallığı olarak kurulmuş egemen bir devlettir. II. Dünya Savaşı'nda Alman işgaline karşı Josip Broz Tito liderliğinde direnmiş ve savaştan sonra Sosyalist Yugoslavya Federasyonu adını almıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Hindistan: İngiliz sömürgesiyken Mahatma Gandhi'nin pasif direnişiyle 1947'de bağımsızlığını ilan etmiştir.\n• B) Tunus: Fransa sömürgesiyken Habib Burgiba liderliğinde 1956'da bağımsız olmuştur.\n• D) Güney Kore: 1910-1945 arası Japon sömürgesiyken Japonya'nın II. Dünya Savaşı'nda yenilmesiyle 1948'de bağımsız olmuştur.\n• E) Pakistan: İngiliz sömürgesinin sona ermesiyle Muhammed Ali Cinnah liderliğinde 1947'de Hindistan'dan ayrılarak bağımsız olmuştur.\n\n💡 KPSS HAFIZA KARTI:\nII. Dünya Savaşı Sonrası De-kolonizasyon (Sömürgesizleşme):\n• 1955 Bandung Konferansı ile Afrika ve Asya'nın yeni bağımsız ülkeleri bir araya gelerek **\"Bağlantısızlar Hareketi\"**ni (Üçüncü Dünya) kurmuştur (Öncüleri: Tito, Nehru, Nasır).",
    "isMapQuestion": false,
