    "questionText": "12 Ocak 1920’de açılan Son Osmanlı Mebusan Meclisinin ilk başkanlığını aşağıdakilerden hangisi yürütmüştür?",
    "options": {
      "A": "Reşat Hikmet Bey",
      "B": "Rauf Orbay",
      "C": "Celalettin Arif",
      "D": "Ahmet Vefik",
      "E": "Server Paşa"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Reşat Hikmet Bey\n12 Ocak 1920'de İstanbul'da toplanan Son Osmanlı Mebusan Meclisi açıldığında, yapılan gizli oylama sonucunda meclisin İLK BAŞKANLIĞINA **Reşat Hikmet Bey** seçilmiştir. Ancak Reşat Hikmet Bey çok kısa bir süre sonra vefat edince yerine son başkan olarak **Celalettin Arif Efendi** seçilmiştir (Celalettin Arif Efendi İstanbul işgal edilince Ankara'ya geçerek TBMM'ye katılmıştır).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Rauf Orbay: Son Osmanlı Mebusan Meclisi'nde Mustafa Kemal'in kurdurmak istediği \"Müdafaa-i Hukuk\" yerine kurulan \"Felah-ı Vatan\" (Vatanın Kurtuluşu) grubunun başkanıdır.\n• C) Celalettin Arif: Reşat Hikmet Bey'in vefatından sonra seçilen Mebusan Meclisi'nin SON başkanıdır; Ankara'da TBMM 2. başkanlığı ve Adalet Bakanlığı yapmıştır.\n• D) Ahmet Vefik Paşa: Osmanlı'da 1877'de toplanan I. Meşrutiyet Mebusan Meclisi'nin ilk başkanıdır.\n• E) Server Paşa: I. Meşrutiyet dönemi Ayan Meclisi başkanıdır.\n\n💡 KPSS HAFIZA KARTI:\nMebusan Meclisi Ayrımı:\n• Mustafa Kemal Meclis Başkanlığına aday olmak istemiş ancak seçilememiştir.\n• İlk seçilen başkan: **Reşat Hikmet Bey**\n• Vefatından sonraki son başkan: **Celalettin Arif Efendi**",
    "isMapQuestion": false,
    "file": "20260904_235441.jpg"
