    "questionText": "Sivas'ta ulusal bir kongrenin toplanmasına aşağıdakilerden hangisinde karar verilmiştir?",
    "options": {
      "A": "Amasya Genelgesi'nde",
      "B": "Erzurum Kongresi'nde",
      "C": "Bilecik Görüşmelerinde",
      "D": "Büyük Millet Meclisi'nde",
      "E": "Amasya Görüşmelerinde"
    },
    "markedAnswer": "B",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Amasya Genelgesi'nde (Tamimi - 22 Haziran 1919)\nAmasya Genelgesi'nin 5. maddesinde: **\"Anadolu'nun her bakımdan en güvenli yeri olan Sivas'ta milli bir kongrenin tez elden toplanması kararlaştırılmıştır. Bunun için her sancaktan milletin güvenini kazanmış üç delegenin derhal yola çıkarılması gerekmektedir\"** kararı alınmıştır. Sivas Kongresi'nin toplanma çağrısı ve kararı ilk kez Amasya'da dünyaya ilan edilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Erzurum Kongresi: Doğu Anadolu Müdafaa-i Hukuk Cemiyeti öncülüğünde bölgesel toplanan kongredir.\n• C) Bilecik Görüşmeleri (Aralık 1920): Mustafa Kemal ile İstanbul Hükümeti temsilcileri (Ahmet İzzet ve Salih Paşalar) arasında tren istasyonunda yapılan görüşmedir.\n• D) Büyük Millet Meclisi (TBMM): 23 Nisan 1920'de Ankara'da açılan kurucu meclistir.\n• E) Amasya Görüşmeleri (Protokolleri): Temsil Heyeti ile İstanbul Hükümeti arasında yapılan ve Mebusan Meclisi'nin toplanmasını sağlayan uzlaşmadır.\n\n💡 KPSS HAFIZA KARTI:\nAmasya Genelgesi'nin Tarihi Özeti:\n• Kurtuluş Savaşı'nın Gerekçesi, Amacı ve Yöntemi ilk kez açıklandı.\n• İhtilal Beyannamesi niteliğindedir.\n• Mustafa Kemal bu genelgeden sonra (Erzurum Kongresi öncesinde) askerlik mesleğinden istifa ederek \"Sine-i Millete\" dönmüştür.",
