    "subjectNumber": 135,
    "categoryOrder": 9,
    "category": "Milli Mücadele Hazırlık Dönemi ve I. TBMM Dönemi",
    "topic": "Kurtuluş Savaşı Muharebeler Dönemi (Londra Konferansı ve Dış Politika)",
    "questionText": "Londra Konferansı'nda TBMM'yi temsil eden ve burada Misakımillî'ye aykırı ikili anlaşmalar imzaladığı gerekçesiyle görevinden istifa eden Hariciye Vekili aşağıdakilerden hangisidir?",
    "options": {
      "A": "Yusuf Kemal Bey",
      "B": "Ali Fuat Paşa",
      "C": "Tevfik Paşa",
      "D": "Bekir Sami Bey",
      "E": "Rauf Bey"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Bekir Sami Bey (Kunduh)\nI. İnönü Zaferi'nden sonra toplanan 1921 Londra Konferansı'nda TBMM'yi Hariciye Vekili (Dışişleri Bakanı) **Bekir Sami Bey** temsil etmiştir. Bekir Sami Bey, konferans sırasında İngiltere, Fransa ve İtalya ile esir değişimi ve ekonomik imtiyazlar öngören ikili anlaşmalar imzalamıştır. Bu anlaşmalar **Misakımilli'ye ve devletin tam bağımsızlık ilkesine aykırı tavizler içerdiği için** TBMM tarafından reddedilmiş ve Bekir Sami Bey bakanlık görevinden istifa ettirilmiştir. Yerine **Yusuf Kemal Tengirşenk** atanmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Yusuf Kemal Tengirşenk: Bekir Sami Bey'in yerine Dışişleri Bakanı olan ve 1921 Moskova Antlaşması ile Fransızlarla Ankara Antlaşması'nı imzalayan diplomattır.\n• B) Ali Fuat Paşa (Cebesoy): Gediz Taarruzu'ndaki başarısızlıktan sonra Moskova Büyükelçiliği'ne gönderilen komutandır.\n• C) Tevfik Paşa: Londra Konferansı'nda Osmanlı Devleti'ni temsil eden son sadrazamdır (\"Söz milletin asıl vekili olan TBMM heyetinindir\" demiştir).\n• E) Rauf Bey (Orbay): Mondros'u imzalayan, daha sonra TBMM İcra Vekilleri Heyeti başkanlığı yapan liderdir.\n\n💡 KPSS HAFIZA KARTI:\nLondra Konferansı (1921) Önemi:\nİtilaf Devletleri, TBMM heyetini resmi olarak davet ederek **TBMM'nin varlığını hukuken ilk kez tanımışlardır!**",
