    "questionText": "İstanbul'un işgalini Mustafa Kemal'e bildiren ve daha sonra Mustafa Kemal'in talimatı ile Temsil Heyetinin karargâhında Millî Mücadele'ye destek olan telgraf memuru kimdir?",
