    "explanation": "✅ DOĞRU CEVAP: B) Tüm ticaret gemileri boğazlardan serbestçe geçebilecek\nHem 1923 Lozan Barış Antlaşması'na ekli Boğazlar Sözleşmesi'nde hem de 1936 Montrö Boğazlar Sözleşmesi'nde; **\"Barış zamanında, bayrağı ve yükü ne olursa olsun tüm sivil ticaret gemilerinin Boğazlar'dan serbestçe geçiş hakkına sahip olduğu\"** ilkesi AYNEN korunmuş ortak temel maddedir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Boğazlar Komisyonu'nun kaldırılması: Lozan'da komisyon vardı (Başkanı Türk olan uluslararası komisyon); Montrö ile bu komisyon tamamen kaldırılmıştır (Ortak değildir).\n• C) Asker bulundurma hakkı: Lozan'da Boğazların her iki yakası 15 km silahsızlandırılmıştı; Montrö ile Türkiye Boğazlara asker ve top yerleştirme hakkı kazanmıştır (Ortak değildir).\n• D & E) Savaş gemilerine tonaj sınırlaması ve Karadeniz'de kalma süresi (21 gün): Lozan'da olmayan, Montrö ile getirilen çok sıkı sınırlamalardır.\n\n💡 KPSS HAFIZA KARTI:\nLozan vs. Montrö Karşılaştırması:\n• Lozan Boğazlar Maddesi = Egemenliğimizi kısıtlayan bir tavizdi (Uluslararası komisyon + Silahsız bölge).\n• Montrö (1936) = Boğazlar Komisyonu kaldırıldı, asker sokuldu, tam egemenlik Türkiye'ye geçti.",
