    "explanation": "✅ DOĞRU CEVAP: C) Yunanistan\n11 Ekim 1922'de imzalanan Mudanya Ateşkes Antlaşması konferansına TBMM (İsmet Paşa başkanlığında), İngiltere (General Harington), Fransa (General Charpy) ve İtalya (General Mombelli) katılmıştır. Mağlup olan **Yunanistan temsilcileri (General Mazarakis) Mudanya açıklarında bir İngiliz zırhlısında beklemiş, doğrudan masaya oturmamış ve antlaşmayı ancak 3 gün sonra Atina'da imzalamıştır**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İngiltere: Lloyd George hükümeti Mudanya'da Türk ordusunun Boğazlar ve Trakya'ya yürüme kararlılığı karşısında savaşı göze alamayarak masaya oturmuştur (Sonrasında Lloyd George hükümeti istifa etmiştir).\n• B) Fransa: Türk tezlerini desteklemiş ve Franklin Bouillon aracılığıyla arabuluculuk yapmıştır.\n• D) Türkiye: İsmet Paşa'nın askeri ve diplomatik dehasıyla Doğu Trakya, Boğazlar ve İstanbul tek kurşun atılmadan kurtarılmıştır.\n• E) İtalya: İngiltere'yi yalnız bırakarak Türk tezlerine yakın durmuştur.\n\n💡 KPSS HAFIZA KARTI:\nMudanya Ateşkes Antlaşması'nın (1922) En Büyük Kazanımları:\n1. Kurtuluş Savaşı'nın askeri safhası bitti, diplomatik safhası başladı.\n2. **Doğu Trakya, Boğazlar ve İstanbul SAVAŞ YAPILMADAN KURTARILDI.**\n3. İstanbul hükümeti yok sayılarak Osmanlı Devleti HUKUKEN sona erdi.",
