    "explanation": "✅ DOĞRU CEVAP: A) Sakarya Meydan Savaşı (23 Ağustos - 13 Eylül 1921)\nMustafa Kemal Paşa, Kütahya-Eskişehir yenilgisinden sonra Başkomutanlık yetkisini alarak yönettiği 22 gün 22 gece süren kanlı Sakarya Meydan Muharebesi sırasında, ordu ricat ederken dünya askeri harp tarihine geçen şu tarihi emri vermiştir:\n**\"Hatt-ı müdafaa yoktur, sath-ı müdafaa vardır. O satıh bütün vatandır. Vatanın her karış toprağı vatandaşın kanıyla ıslanmadıkça terk olunamaz!\"** Bu emirle klasik cephe harbi anlayışı terk edilmiş, topyekûn vatan savunması doktrinine geçilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Büyük Taarruz (26 Ağustos 1922): Mustafa Kemal'in \"Ordular! İlk hedefiniz Akdeniz'dir, ileri!\" emrini verdiği taarruz savaşıdır.\n• C) I. İnönü Savaşı: Düzenli ordunun Batı Cephesi'ndeki ilk savunma zaferidir.\n• D) II. İnönü Savaşı: Mustafa Kemal'in \"Siz orada yalnız düşmanı değil, milletin makûs talihini de yendiniz\" telgrafını çektiği savaştır.\n• E) Eskişehir-Kütahya Savaşları: Kurtuluş Savaşı'ndaki tek yenilgimiz olup ordunun Sakarya'nın doğusuna çekildiği savaştır.\n\n💡 KPSS HAFIZA KARTI:\nSakarya Zaferi'nin Unvanları:\n• Mustafa Kemal'e TBMM tarafından **\"Gazi\"** unvanı ve **\"Mareşal\"** rütbesi verilmiştir.\n• Savaşta çok fazla subay şehit düştüğü için **\"Subaylar Savaşı (Melhame-i Kübra)\"** olarak da anılır.",
