    "questionText": "Türkiye, Misakımilli sınırlarına dâhil olan Musul'u topraklarına katmak adına bir askerî harekât hazırlığı yaparken Şeyh Sait İsyanı patlak vermiştir. İsyan nedeniyle zor durumda kalan Türkiye, Musul'u Irak yönetimine bırakmak zorunda kalmıştır.\nBuna göre Türkiye'nin Musul'u kaybettiği antlaşma aşağıdakilerden hangisidir?",
    "options": {
      "A": "Montrö",
      "B": "İstanbul",
      "C": "Moskova",
      "D": "Londra",
      "E": "Ankara"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) 1926 Ankara Antlaşması\nMisakımillî sınırları içinde yer alan Musul vilayetini kurtarmak için Türkiye askeri harekât hazırlığı yaparken, 1925 yılında İngiltere'nin kışkırtmasıyla patlak veren kanlı **Şeyh Sait İsyanı** sebebiyle ordunun dikkati iç güvenliğe yönelmiş ve Musul'a askeri harekât yapılamamıştır. Türkiye, 5 Haziran 1926 tarihinde İngiltere ve Irak hükümeti ile imzalanan **Ankara Antlaşması** ile Musul ve Kerkük'ü Irak'a bırakmak zorunda kalmış; petrol gelirlerinin %10'u 25 yıl süreyle Türkiye'ye bırakılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Montrö Sözleşmesi (1936): Boğazlar Komisyonu'nun kaldırıldığı ve Boğazların tam egemenliğinin Türkiye'ye geçtiği sözleşmedir.\n• B) 1913 İstanbul Antlaşması: II. Balkan Savaşı sonunda Bulgaristan ile imzalanan antlaşmadır.\n• C) 1921 Moskova Antlaşması: Sovyet Rusya ile imzalanan dostluk antlaşmasıdır (Batum bırakılmıştır).\n• D) 1921 Londra Konferansı: I. İnönü sonrası İtilaf Devletleri ile yapılan konferanstır.\n\n💡 KPSS HAFIZA KARTI:\nMisakımilli'den Verilen 3 Büyük Taviz:\n1. Batum (1921 Moskova Antlaşması ile Gürcistan'a) - İlk Taviz\n2. Hatay (1921 Ankara Antlaşması ile Fransız mandasındaki Suriye'ye - 1939'da anavatana katıldı)\n3. Musul (1926 Ankara Antlaşması ile İngiliz mandasındaki Irak'a).",
