    "explanation": "✅ DOĞRU CEVAP: B) Kars Muharebesi (Doğu Harekâtı - 1920)\n23 Nisan 1920'de açılan TBMM'ye bağlı askerî kuvvetlerin kazandığı TARİHTEKİ İLK ASKERÎ ZAFER; Doğu Cephesi Komutanı **Kazım Karabekir** Paşa komutasındaki 15. Kolordu'nun Ermenilere karşı yürüttüğü **Doğu Harekâtı (Kars ve Sarıkamış'ın kurtarılması)**dır. Bu zafer sonucunda 3 Aralık 1920'de imzalanan Gümrü Antlaşması da TBMM'nin ilk diplomatik zaferi olmuştur. I. İnönü Muharebesi ise TBMM'nin kurduğu YENİ DÜZENLİ ORDUNUN BATI CEPHESİ'NDEKİ İLK ZAFERİDİR.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Aslıhanlar-Dumlupınar Muharebesi (Nisan 1921): II. İnönü Zaferi'nin ardından Refet Bele komutasındaki birliklerin Yunan mevzilerine yaptığı ancak ordunun henüz taarruz gücüne ulaşamadığını gösteren deneme taarruzudur.\n• C) Kütahya-Eskişehir Muharebesi (Temmuz 1921): Kurtuluş Savaşı'ndaki tek mağlubiyetimizdir.\n• D) I. İnönü Muharebesi (Ocak 1921): TBMM'nin kurduğu düzenli ordunun Batı Cephesi'ndeki ilk zaferidir.\n• E) Gediz Taarruzu (Ekim 1920): Ali Fuat Paşa ve Çerkez Ethem'in Yunanlılara karşı yaptığı başarısız taarruzdur (Düzenli orduya geçiş kararını hızlandırmıştır).\n\n💡 KPSS HAFIZA KARTI:\nİlk Zaferler Ayrımı:\n• TBMM'nin kazandığı İLK askeri zafer: **Kars / Doğu Harekâtı (Kazım Karabekir)**\n• Batı Cephesi'nde Düzenli Ordunun kazandığı İLK zafer: **I. İnönü Savaşı (İsmet İnönü)**",
