    "questionText": "7 - 8 Ağustos 1921 tarihinde yayımlanan Tekâlif-i Milliye Emirleri doğrultusunda halk;\n\nI. elindeki her türlü silah ve cephaneyi 3 gün içinde teslim edecek,\nII. her aile bir kat çamaşır, bir çift çorap ve çarık hazırlayacak,\nIII. taşıt sahipleri ayda bir defa 100 kilometrelik mesafeye ücretsiz askerî malzeme taşıyacak\n\nkararlarından hangilerini yerine getirmekle yükümlü kılınmıştır?",
