    "questionText": "Lozan Barış Antlaşması’nda yer alan aşağıdaki konulardan hangisi Türkiye’nin ulusal egemenliğini ve bağımsızlığını kısıtlayıcı bir şekilde çözüme kavuşturulmuştur?",
