    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Boğazlar\nLozan Barış Antlaşması'nda Türkiye'nin egemenlik haklarını ve tam bağımsızlığını açıkça kısıtlayan en önemli madde **Boğazlar Maddesi**dir:\n1. Boğazların yönetimi Türkiye'ye değil, başkanı Türk olan uluslararası bir **Boğazlar Komisyonu'na** bırakılmıştır.\n2. Boğazların her iki yakası askerden ve silahlardan arındırılmıştır (Türkiye kendi toprağına asker sokamamıştır).\nBu durum ulusal egemenliğimize aykırı olup, 1936 yılında imzalanan **Montrö Boğazlar Sözleşmesi** ile komisyon kaldırılarak düzeltilmiştir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Kapitülasyonlar: Lozan'da adli, mali ve idari tüm kapitülasyonlar koşulsuz şartsız tamamen kaldırılmıştır (Büyük zafer).\n• C) Yabancı Okullar: Türkiye'nin bir iç meselesi sayılmış ve tamamı Türk Milli Eğitim Bakanlığı'nın kanunlarına bağlanmıştır (Taviz verilmedi).\n• D) Duyun-ı Umumiye: İdari varlığı sona erdirilmiş, sadece borç ödeme planı yapılmıştır.\n• E) Azınlıklar: Bütün gayrimüslimler Türk vatandaşı sayılmış ve ayrıcalıklarına son verilmiştir.\n\n💡 KPSS HAFIZA KARTI:\nLozan'da Çözülemeyen / Sonraya Bırakılan Tek Konu:\n**Musul Sorunu (Türkiye-Irak Sınırı)** - İngiltere ile Türkiye arasında 9 ay içinde ikili görüşmelere bırakılmıştır.",
