    "questionText": "Millî Mücadele sırasında İtalyanların işgal ettikleri Antalya, Konya ve Muğla'yı boşaltmaya başlamaları ve Fransızların Zonguldak'tan çekilmeleri hangi savaşın sonuçları arasında yer almıştır?",
