    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) II. İnönü Savaşı (Mart - Nisan 1921)\n23 Mart - 1 Nisan 1921 tarihlerinde yapılan II. İnönü Savaşı'nda Türk ordusunun Yunanlıları ikinci kez mağlup etmesi üzerine İtilaf Devletleri arasındaki birlik tamamen çatlamıştır. **İtalya, Türk milletinin azmini görerek işgal ettiği Antalya, Konya ve Muğla bölgelerini kademeli olarak boşaltmaya ve Anadolu'dan çekilmeye başlamıştır**. (Fransa da Zonguldak'tan çekilmiş ve barış görüşmeleri için Franklin Bouillon'u Ankara'ya göndermiştir).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Sakarya Meydan Muharebesi: Sakarya Zaferi sonrasında İtalya Anadolu'yu TAMAMEN boşaltmış, Fransa ile Ankara Antlaşması imzalanmıştır.\n• B) Kütahya-Eskişehir Savaşları: Türk ordusu yenilince İtalyanlar çekilme işlemini geçici olarak durdurup beklemiştir; ancak Sakarya Zaferi ile tamamen gitmişlerdir.\n• C) I. İnönü Savaşı: İtilaf Devletleri Londra Konferansı'nı toplamıştır.\n• D) Büyük Taarruz: Yunan ordusunun denize döküldüğü ve tüm Batı Anadolu'nun kurtarıldığı taarruzdur.\n\n💡 KPSS HAFIZA KARTI:\nİtilaf Devletlerinin Ayrışması:\n• Anadolu'dan çekilmeye başlayan İLK İtilaf Devleti = **İtalya** (II. İnönü sonrası)\n• TBMM'yi tanıyan ve Güney Cephesini kapatan İLK İtilaf Devleti = **Fransa** (Sakarya sonrası 1921 Ankara Antlaşması).",
