    "topic": "Atatürk Dönemi Kültür ve Bilim",
    "questionText": "Cumhuriyet Dönemi’nde Türk tarihi ve kültürü üzerine bilimsel araştırmalar yapmak amacıyla kurulan kurumlar arasında aşağıdakilerden hangisi doğrudan yer almaz?",
    "options": {
      "A": "Türk Tarih Kurumu",
      "B": "Dil ve Tarih-Coğrafya Fakültesi",
      "C": "Türk Tarihi Tetkik Cemiyeti",
      "D": "Türkiyat Enstitüsü",
      "E": "Türk Dil Kurumu"
    },
    "markedAnswer": "C",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Türk Dil Kurumu (12 Temmuz 1932)\n12 Temmuz 1932 tarihinde Atatürk'ün direktifleriyle bizzat kurulan (ilk adı Türk Dili Tetkik Cemiyeti olan) **Türk Dil Kurumu**; Türkçenin zenginliğini ortaya çıkarmak, yabancı dillerin boyunduruğundan kurtarıp özleştirmek, bilim ve edebiyat dili haline getirmek ve Türkçe sözlükler hazırlamak amacıyla kurulmuş en köklü kültür kurumudur. İlk başkanı Samih Rıfat Bey'dir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Türk Tarih Kurumu (1931): Türk tarihini hanedan tarihinden çıkarıp köklü millet tarihi olarak araştırmak için kurulmuştur (İlk başkanı Tevfik Bıyıklıoğlu).\n• B) Dil ve Tarih-Coğrafya Fakültesi (DTCF - 1935): Ankara'da Türk dili, tarihi ve arkeolojisi alanında uzman akademisyen yetiştirmek amacıyla Atatürk tarafından kurulan ilk fakültedir.\n• C) Türk Tarihi Tetkik Cemiyeti: Türk Tarih Kurumu'nun ilk resmi adıdır.\n• D) Türkiyat Enstitüsü (1924): Fuat Köprülü öncülüğünde İstanbul Darülfünunu bünyesinde kurulan Türkoloji araştırma merkezidir.\n\n💡 KPSS HAFIZA KARTI:\nAtatürk'ün Vasiyeti:\nMustafa Kemal Atatürk, İş Bankası'ndaki hisselerinin nemasını (gelirlerini) vasiyetnamesiyle **Türk Dil Kurumu ve Türk Tarih Kurumu'na** bırakmıştır!",
