    "questionText": "Türkiye Cumhuriyeti'nin 2000'li yıllardan itibaren sınırları içinde ve sınır ötesinde mücadele ettiği terör örgütleri arasında aşağıdakilerden hangisi gösterilemez?",
    "options": {
      "A": "ASALA",
      "B": "DEAŞ",
      "C": "FETÖ",
      "D": "PKK",
      "E": "PYD"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) ASALA (Ermenistan'ın Kurtuluşu İçin Ermeni Gizli Ordusu)\nASALA terör örgütü, 2000'li yıllarda değil; **1975 ile 1985 yılları arasında (1970'ler ve 1980'lerde)** faaliyet göstermiş; aralarında Viyana, Paris, Lizbon ve Los Angeles'ın da bulunduğu dünya başkentlerinde 42 Türk diplomatını ve aile fertlerini kalleşçe şehit eden marksist-milliyetçi Ermeni terör örgütüdür (1985 sonrasında yerini PKK iş birliğine bırakarak tasfiye olmuştur).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) DEAŞ (IŞİD): 2010'lu yıllarda ortaya çıkan, Türkiye'nin Fırat Kalkanı Harekâtı (2016) ile sınır ötesinde doğrudan savaştığı küresel terör örgütüdür.\n• C) FETÖ: 15 Temmuz 2016 hain darbe girişimini gerçekleştiren ve 2000'li yıllarda tasfiye edilen devlete sızmış terör şebekesidir.\n• D) PKK: 1984'ten günümüze ve 2000'li yıllarda da sınır içi ve sınır ötesinde (Pençe-Kilit vb.) mücadele edilen bölücü terör örgütüdür.\n• E) PYD/YPG: PKK'nın Suriye uzantısı olup Türkiye'nin Zeytin Dalı (Afrin) ve Barış Pınarı harekatlarıyla mücadele ettiği terör örgütüdür.\n\n💡 KPSS HAFIZA KARTI:\nASALA'nın İlk Şehit Ettiği Diplomatlarımız:\n27 Ocak 1973'te Los Angeles Başkonsolosu **Mehmet Baydar** ve Konsolos **Bahadır Demir**, Ermeni terörist Yanikyan tarafından şehit edilmiştir.",
