    "questionText": "• İngiltere'de hukuk eğitimi almış, 1955'te Enosis'le mücadele ederek Kıbrıs'ta Türk Mukavemet Teşkilatı'nı kurmuştur.\n• 1974'teki Kıbrıs Barış Harekâtı sonrasında kurulan Kuzey Kıbrıs Türk Cumhuriyeti'nin cumhurbaşkanlığı görevini yürütmüştür.\nVerilen özellikler aşağıdakilerden hangisine aittir?",
    "options": {
      "A": "Rauf Denktaş",
      "B": "Ferit Melen",
      "C": "Mehmet Ali Talat",
      "D": "Nihat Erim",
      "E": "Fazıl Küçük"
    },
    "markedAnswer": "A",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Rauf Denktaş\nİngiltere'de Lincoln's Inn'de hukuk eğitimi alan, Kıbrıs Başsavcı yardımcılığı yapan; 1955'te EOKA terörüne ve Enosis (Kıbrıs'ı Yunanistan'a bağlama) hayaline karşı Dr. Fazıl Küçük ve Burhan Nalbantoğlu ile birlikte **Türk Mukavemet Teşkilatı (TMT)**'nı kuran ve \"Toros\" kod adıyla direnişi yöneten, 15 Kasım 1983'te kurulan **Kuzey Kıbrıs Türk Cumhuriyeti'nin (KKTC) KURUCU CUMHURBAŞKANI** olan efsanevi lider **Rauf Raif Denktaş**tır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Ferit Melen: 12 Mart muhtırası sonrasında 1972-1973 yıllarında Türkiye Cumhuriyeti Başbakanlığı yapmış siyasetçidir.\n• C) Mehmet Ali Talat: KKTC'nin 2. Cumhurbaşkanıdır (2005-2010).\n• D) Nihat Erim: 12 Mart 1971 muhtırasından sonra kurulan teknokrat hükümetinin Başbakanıdır.\n• E) Dr. Fazıl Küçük: Kıbrıs Türk halkının milli mücadelesinin ilk lideri, \"Halkın Sesi\" gazetesinin sahibi ve 1960 Kıbrıs Cumhuriyeti'nin ilk Türk Cumhurbaşkanı Yardımcısıdır.\n\n💡 KPSS HAFIZA KARTI:\nKıbrıs Kahramanları:\n• TMT Lideri ve KKTC Kurucu Cumhurbaşkanı = **Rauf Denktaş**\n• Kıbrıs Türk Halk Lideri = **Dr. Fazıl Küçük**\n• 1974 Barış Harekâtı Hükümeti = **Bülent Ecevit & Necmettin Erbakan**",
