    "topic": "Temel Hukuk Kavramları / Uyuşmazlık Çözüm Yolları",
    "questionText": "Taraflar arasında çıkan uyuşmazlıkların devletin resmî yargı organları yerine, kendileri tarafından belirlenen hakemlerce çözümlendiği uyuşmazlık çözüm yöntemine ne ad verilir?",
    "options": {
      "A": "Uzlaştırma",
      "B": "Tahkim",
      "C": "Ara buluculuk",
      "D": "Konkordato",
      "E": "Kavuşturma"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) Tahkim\nUyuşmazlığın taraflarının aralarındaki hukuki anlaşmazlığı devletin resmî mahkemeleri yerine, bağımsız ve tarafsız kişi veya heyetlerden oluşan hakemlere bırakması ve bu hakem kararının mahkeme ilamı gibi bağlayıcı olması yöntemine **TAHKİM** denir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Uzlaştırma: Ceza muhakemesinde uzlaşmaya tabi suçlarda fail ile mağdurun uzlaştırmacı nezaretinde anlaşarak uyuşmazlığı sonlandırmasıdır.\n• C) Ara buluculuk: Hukuk uyuşmazlıklarında tarafları iletişime geçiren üçüncü kişinin bağlayıcı karar vermeksizin çözümü taraflara bıraktığı alternatif yoldur.\n• D) Konkordato: Borçlarını vadesinde ödeyemeyen borçlunun iflastan kurtulmak için alacaklılarıyla yaptığı mahkeme onaylı borç yapılandırmasıdır.\n• E) Kovuşturma: Ceza yargılamasında iddianamenin kabulü ile başlayıp kesin hükme kadar devam eden mahkeme evresidir.\n\n💡 KPSS HAFIZA KARTI:\nUyuşmazlık Çözüm Yolları:\n• Tahkim = Hakem eliyle bağlayıcı ilam niteliğinde karar.\n• Arabuluculuk = Tarafların kendi iradesiyle anlaşması (Bağlayıcı karar vermez).\n• Soruşturma = Suç şüphesi -> İddianamenin kabulü (Savcılık).\n• Kovuşturma = İddianamenin kabulü -> Kesin hüküm (Mahkeme).",
