    "questionText": "6098 sayılı Türk Borçlar Kanunu’na göre, aşağıdakilerden hangisi borcu sona erdiren hâller arasında gösterilemez?",
    "options": {
      "A": "İfa",
      "B": "İbra",
      "C": "Tecdit",
      "D": "Takas",
      "E": "Def'i"
    },
    "markedAnswer": "E",
    "correctAnswer": "E",
    "explanation": "✅ DOĞRU CEVAP: E) Def'i\n6098 sayılı Türk Borçlar Kanunu'na göre borcu sona erdiren genel sebepler: İfa, İbra, Yenileme (Tecdit), Alacaklı ve borçlu sıfatlarının birleşmesi, Kusursuz imkânsızlık ve Takas'tır. **DEF'İ İSE BORCU SONA ERDİRMEZ**; borçlunun var olan borcunu yerine getirmekten haklı bir kanuni gerekçeyle (örneğin zamanaşımı def'i ile) kaçınmasını sağlayan bir **SAVUNMA HAKKIDIR**. Def'i ileri sürüldüğünde borç yok olmaz; sadece dava edilemez bir **\"Eksik Borç\"** haline gelir.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İfa: Borçlunun borçlandığı edimi tam ve eksiksiz yerine getirmesiyle borcu doğal olarak sona erdirir.\n• B) İbra: Alacaklının alacağından vazgeçerek borçluyu borçtan aklaması (kurtarması) sözleşmesidir.\n• C) Tecdit (Yenileme): Mevcut bir borcun yerine yeni bir borç meydana getirilerek eski borcun sona erdirilmesidir.\n• D) Takas: Karşılıklı, aynı cinsten ve muaccel (vadesi gelmiş) iki borcun birbirinden mahsup edilerek son bulmasıdır.\n\n💡 KPSS HAFIZA KARTI:\nBorcu Sona Erdirenler vs Eksik Borç Yapanlar:\n• Borcu Sona Erdirenler: **İfa, İbra, Tecdit, Takas, Birleşme, Kusursuz İmkânsızlık**.\n• Borcu Sona ErdirMEYENLER (Eksik Borç): **Zamanaşımı, Def'i, Kumar ve bahis borçları, Evlenme tellallığı**.",
    "isMapQuestion": false,
