    "questionText": "46. Sözleşmenin tarafları her durumda sözleşmeye riayet etmeli, ona sadık kalmalı şeklindeki açıklama aşağıdaki ilkelerden hangisiyle ifade edilir?",
    "options": {
      "A": "Ahde vefa",
      "B": "Emprevizyon",
      "C": "Müsadere",
      "D": "Def'i",
      "E": "Sebepsiz zenginleşme"
    },
    "markedAnswer": "D",
    "correctAnswer": "A",
    "explanation": "✅ DOĞRU CEVAP: A) Ahde vefa\nBorçlar hukukunda **Ahde Vefa (Pacta Sunt Servanda - Söze Bağlılık)** ilkesi; tarafların bir sözleşmeyi serbest iradeleriyle kurduktan sonra şartlar ne kadar değişirse değişsin verdikleri söze ve sözleşme şartlarına aynen riayet etmek ve borçlarını yerine getirmek zorunda olmalarını ifade eder.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• B) Emprevizyon: Ahde vefa ilkesinin istisnası olan \"Beklenmeyen Hal Teorisi\"dir; koşulların olağanüstü ve öngörülemez şekilde değişmesi durumunda hâkimden sözleşmenin uyarlanmasını talep etme hakkıdır.\n• C) Müsadere: Suç konusu eşyanın veya suçtan elde edilen gelirin mülkiyetinin devlete geçirilmesidir (Genel müsadere 1982 Anayasası'nda yasaktır).\n• D) Def'i: Borçlunun borcu ödemekten kaçınmasını sağlayan savunma aracıdır (örn. zamanaşımı).\n• E) Sebepsiz zenginleşme: Haklı bir hukuki sebep olmaksızın bir kimsenin malvarlığının bir başkası aleyhine çoğalmasıdır.\n\n💡 KPSS HAFIZA KARTI:\nSözleşme İlkeleri:\n• **Ahde Vefa:** Söze sadakat kuralı (Sözleşmeye bağlılık esastır).\n• **Emprevizyon:** Koşulların altüst olması halinde sözleşmenin uyarlanması istisnası.\n• **Gabin:** Aşırı yararlanma (Zor durumdan istifade ederek fahiş menfaat sağlama).",
