    "topic": "Yasama / TBMM ve Siyasi Parti Grupları",
    "questionText": "“Yediiklim Partisi” olarak TBMM’de grup hâline gelen partinin yapabileceği işlemler arasında aşağıdakilerden hangisi gösterilemez?",
    "options": {
      "A": "Meclis araştırması teklifi",
      "B": "TBMM Başkanlığına aday gösterme",
      "C": "Genel görüşme teklifi",
      "D": "Cumhurbaşkanlığına aday gösterme",
      "E": "Kapalı oturum isteme"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) TBMM Başkanlığına aday gösterme\n1982 Anayasası'nın 94. maddesi son fıkrasının emredici hükmü şudur: **\"Türkiye Büyük Millet Meclisi'ndeki siyasi parti grupları, Meclis Başkanlığı için aday gösteremezler.\"** Bu kuralın amacı, Meclis Başkanının tarafsızlığını korumak ve siyasi baskı altına girmesini engellemektir. Milletvekilleri Meclis Başkanlığına yalnızca şahsi olarak bireysel başvuruda bulunabilirler.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Meclis araştırması teklifi: Siyasi parti grupları Meclis araştırması açılmasını teklif edebilirler.\n• C) Genel görüşme teklifi: Toplumu veya devleti ilgilendiren bir konunun genel kurulda görüşülmesini parti grupları isteyebilir.\n• D) Cumhurbaşkanlığına aday gösterme: TBMM'de grubu bulunan siyasi partiler Cumhurbaşkanı adayı gösterebilir.\n• E) Kapalı oturum isteme: Parti grupları genel kurulun kapalı oturumla toplanmasını talep edebilirler.\n\n💡 KPSS HAFIZA KARTI:\nTBMM Siyasi Parti Grupları (En az 20 Milletvekili ile kurulur):\n• **YASAK OLAN TEK FAALİYET:** TBMM Başkanlığına ADAY GÖSTEREMEZLER!\n• **Yapabildikleri:** Cumhurbaşkanlığına aday gösterme, Genel görüşme isteme, Meclis araştırması isteme, Kapalı oturum isteme, Komisyonlara oranlarına göre üye verme.",
