    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) I ve IV (Düşünceyi açıklama ve yayma hürriyeti ile İspat hakkı)\nJellinek'in Anayasa Hukukundaki temel haklar sınıflaması:\n1. **Negatif Statü (Kişi Hak ve Ödevleri / Koruyucu Haklar):** Bireyi devlete karşı koruyan, devletin dokunamayacağı haklardır (**I. Düşünceyi açıklama ve yayma hürriyeti** ile **IV. İspat hakkı** kişi haklarıdır).\n2. **Pozitif Statü (Sosyal ve Ekonomik Haklar / İsteme Hakları):** Bireyin devletten hizmet ve destek talep ettiği haklardır (**II. Sanatın ve sanatçının korunması** ile **III. Toprak mülkiyeti** sosyal-ekonomik haklardır).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Düşünceyi açıklama ve yayma hürriyeti: Kişi Hakları (Negatif Statü).\n• II. Sanatın ve sanatçının korunması: Sosyal ve Ekonomik Haklar (Pozitif Statü).\n• III. Toprak mülkiyeti: Sosyal ve Ekonomik Haklar (Pozitif Statü - Dikkat: Normal mülkiyet hakkı kişi hakkıyken, \"toprak mülkiyeti\" sosyal haktır!).\n• IV. İspat hakkı: Kişi Hakları (Negatif Statü - Hakaret davalarında ispat hakkı).\n\n💡 KPSS HAFIZA KARTI:\nHakların Sınıflandırılması:\n• Negatif Statü = \"Bana dokunma!\" (Kişi dokunulmazlığı, mülkiyet, konut dokunulmazlığı, düşünce hürriyeti, ispat hakkı).\n• Pozitif Statü = \"Bana yardım et!\" (Eğitim, sağlık, çalışma, konut, sanatın korunması, toprak mülkiyeti).\n• Aktif Statü = \"Yönetime katılıyorum!\" (Seçme-seçilme, parti kurma, vergi, dilekçe, kamu hizmetine girme).",
    "isMapQuestion": false,
    "file": "20260904_235337.jpg"
