    "questionText": "I. Meşru müdafaa\nII. Kişinin kendi rızası\nIII. Tutuklunun kaçmasının önlenmesi\nIV. Ayaklanmanın bastırılması\n\n1982 Anayasası’na göre yukarıdakilerden hangileri, kişinin yaşam hakkına müdahale edilerek öldürme fiilinin işlenmesinin haklı gerekçelerinden gösterilir?",
    "options": {
      "A": "I ve IV",
      "B": "I, III ve IV",
      "C": "I ve III",
      "D": "II ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "B",
    "correctAnswer": "B",
    "explanation": "✅ DOĞRU CEVAP: B) I, III ve IV (Meşru müdafaa, Tutuklunun kaçmasının önlenmesi ve Ayaklanmanın bastırılması)\n1982 Anayasası'nın 17. maddesine göre yaşam hakkına hukuka uygun müdahale (öldürme fiilinin haklı sayıldığı) istisnaları şunlardır:\n1. **Meşru müdafaa (I)**\n2. Yakalama ve tutuklama kararlarının yerine getirilmesi\n3. **Bir tutuklu veya hükümlünün kaçmasının önlenmesi (III)**\n4. **Bir ayaklanma veya isyanın bastırılması (IV)**\n5. Sıkıyönetim veya olağanüstü hallerde yetkili merciin emirlerinin uygulanması.\nKişinin kendi rızası (Ötenazi) Türk hukukunda suçtur; yaşam hakkından vazgeçilemez (II haklı gerekçe olamaz).\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Meşru müdafaa: Can ve namusa yönelik haksız saldırıyı defetmek meşru müdafaadır.\n• II. Kişinin kendi rızası: Ötenazi Türk Ceza Kanunu'nda kasten öldürme sayılır, meşru değildir.\n• III. Tutuklunun kaçmasının önlenmesi: Kaçan silahlı tutukluya karşı orantılı güç kullanımı hukuka uygundur.\n• IV. Ayaklanmanın bastırılması: Kamu düzenini tehdit eden silahlı isyanın bastırılmasında meşru kabul edilir.\n\n💡 KPSS HAFIZA KARTI:\nYaşam Hakkı İstisnaları:\n• Meşru Müdafaa, Firarın Önlenmesi, İsyanın Bastırılması, Yakalama Emri.\n• **TUZAK:** 2004 yılında Ölüm Cezası (İdam) Anayasa'dan tamamen çıkarılmıştır! Ötenazi (kişinin rızası) hukuka aykırıdır.",
