    "questionText": "I. Avrupa İnsan Hakları Sözleşmesi ile devletler güvence altına alınmıştır.\nII. Avrupa İnsan Hakları Sözleşmesi, yalnız insan haklarının korunmasını sağlayan bir belge değil, aynı zamanda Batı demokrasisini somuta indirgeyen bir belgedir.\nIII. İnsan haklarının korunmasının ulusal düzeyden, uluslararası düzeye geçmesini sağlamıştır.\n\nAvrupa İnsan Hakları Sözleşmesi'yle ilgili olarak yukarıdakilerden hangileri doğrudur?",
    "options": {
      "A": "Yalnız I",
      "B": "Yalnız II",
      "C": "I ve II",
      "D": "II ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) II ve III\nAvrupa İnsan Hakları Sözleşmesi (AİHS) ve AİHM'in temel nitelikleri:\n• **I. Yanlış:** AİHS devletleri değil, **BİREYLERİ DEVLETİN İHLALLERİNE KARŞI** güvence altına alır; devletler daima davalı konumundadır.\n• **II. Doğru:** AİHS insan hakları standartlarını ve Batı çoğulcu demokrasisini somut hukuki güvencelere bağlar.\n• **III. Doğru:** Bireylere uluslararası yargı yolunu (AİHM) açarak insan haklarını ulusal sınırların ötesine taşımıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. Madde: AİHS birey merkezlidir, devlet egemenliğini sınırlandırarak vatandaşı korur.\n• II. Madde: Hukuk devleti, bağımsız yargı ve adil yargılanma gibi ilkeleri somutlaştırır.\n• III. Madde: Ulusal mahkemelerin kararları Strazburg'daki AİHM tarafından denetlenebilir.\n\n💡 KPSS HAFIZA KARTI:\nAİHM (Avrupa İnsan Hakları Mahkemesi):\n• Merkezi: **Strazburg (Fransa)**.\n• Bağlı Olduğu Kurum: Avrupa Birliği değil, **Avrupa Konseyi**'dir!\n• Başvuru Şartı: İç hukuk yollarının tamamının (Türkiye'de Anayasa Mahkemesi Bireysel Başvurusu dahil) tüketilmiş olması gerekir.",
