    "questionText": "Aşağıdaki mahalli idare organlarından hangisine aday olmak için mezuniyet şartı aramadan, okuryazar olmak yeterlidir?",
    "options": {
      "A": "Cumhurbaşkanı",
      "B": "Milletvekili",
      "C": "Kaymakam",
      "D": "Köy ve mahalle muhtarları ile ihtiyar heyeti üyesi",
      "E": "Belediye Başkanı"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) Köy ve mahalle muhtarları ile ihtiyar heyeti üyesi\nTürkiye'de seçimle gelinen kamu görevlerinde aranan mezuniyet şartları:\n• Cumhurbaşkanı: En az **Yükseköğrenim (Üniversite)** mezunu olmak.\n• Milletvekili: En az **İlkokul** mezunu olmak.\n• Belediye Başkanı ve Belediye Meclis Üyesi: En az **İlkokul** mezunu olmak.\n• İl Genel Meclisi Üyesi: En az **İlkokul** mezunu olmak.\n• **Köy ve Mahalle Muhtarları ile İhtiyar Heyeti Üyeleri:** Seçilmek için herhangi bir okul diploması şartı aranmaz; **YALNIZCA OKURYAZAR OLMAK YETERLİDİR**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Cumhurbaşkanı: Anayasa madde 101 uyarınca en az 4 yıllık yükseköğrenim mezuniyeti şarttır.\n• B) Milletvekili: Anayasa madde 76 uyarınca en az ilkokul mezunu olmak gerekir.\n• C) Kaymakam: Seçimle değil atamayla gelen kariyer meslek memurudur; 4 yıllık ilgili fakülte mezunu olmalıdır.\n• E) Belediye Başkanı: 5393 sayılı Kanun uyarınca en az ilkokul mezuniyeti şarttır.\n\n💡 KPSS HAFIZA KARTI:\nSeçilme Yeterliliği Mezuniyet Şartları:\n• **Yükseköğrenim (Üniversite):** Cumhurbaşkanı\n• **En Az İlkokul:** Milletvekili, Belediye Başkanı, Belediye Meclisi, İl Genel Meclisi\n• **Yalnızca Okuryazar Olmak:** Muhtar ve İhtiyar Heyeti Üyeleri!",
