    "questionText": "Aşağıdakilerden hangisi merkezi idarenin taşra teşkilatında yer alan birim veya organlardan biri değildir?",
    "options": {
      "A": "İl İdare Kurulu",
      "B": "Kaymakam",
      "C": "İlçe İdare Şube Başkanları",
      "D": "İl Genel Meclisi",
      "E": "Vali"
    },
    "markedAnswer": "D",
    "correctAnswer": "D",
    "explanation": "✅ DOĞRU CEVAP: D) İl Genel Meclisi\nTürkiye'nin idari teşkilat yapısı:\n1. **Merkezi İdarenin Taşra Teşkilatı:** İl Genel İdaresi (Vali, İl İdare Kurulu, İl İdare Şube Başkanları) ve İlçe İdaresi (Kaymakam, İlçe İdare Kurulu, İlçe İdare Şube Başkanları).\n2. **Mahalli İdareler (Yerinden Yönetim):** İl Özel İdaresi, Belediye ve Köy.\n**İl Genel Meclisi**, merkezi idarenin taşra teşkilatına ait bir birim DEĞİL; yerinden yönetim kuruluşu olan **İL ÖZEL İDARESİ'NİN EN YÜKSEK SEÇİLMİŞ KARAR ORGANIDIR**.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) İl İdare Kurulu: Vali başkanlığında toplanan merkezi idare taşra danışma kuruludur.\n• B) Kaymakam: İlçede merkezi idareyi ve Cumhurbaşkanını temsil eden mülki amirdir (Taşra).\n• C) İlçe İdare Şube Başkanları: İlçedeki bakanlık müdürleridir (Taşra).\n• E) Vali: İlde devleti ve Cumhurbaşkanını temsil eden en yetkili mülki idare amiridir (Taşra).\n\n💡 KPSS HAFIZA KARTI:\nİl İdare Kurulu vs İl Genel Meclisi Ayrımı:\n• İl İdare Kurulu = **Merkezi İdare (Taşra Teşkilatı)**.\n• İl Genel Meclisi = **İl Özel İdaresi (Mahalli İdare / Yerinden Yönetim)**.\n• Vali = Hem Devletin ildeki başı (Taşra) hem de İl Özel İdaresi'nin başıdır (Çift Şapkalı).",
