    "explanation": "✅ DOĞRU CEVAP: B) I ve III (İmam ve Öğretmen)\nKöy Kanunu'na göre Köy İhtiyar Meclisi iki tür üyeden meydana gelir:\n1. **Seçilmiş Üyeler:** Köy Derneği (köydeki tüm seçmenler) tarafından 5 yıl için seçilen üyelerdir.\n2. **Doğal (Tabii) Üyeler:** Herhangi bir seçime girmeksizin, yürüttükleri kamu görevi sebebiyle meclisin doğrudan üyesi olan kişilerdir. Bunlar **KÖY İMAMI (I)** ve **KÖY ÖĞRETMENİ / BAŞÖĞRETMEN (III)** dir. Köy çobanı veya doktoru gibi bir doğal üyelik kanunda yoktur.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• I. İmam: Köyün dini görevlisi olup ihtiyar heyetinin doğal üyesidir.\n• II. Çoban: Köy ihtiyar heyeti üyesi değildir; köy derneği veya muhtarlıkça tutulan çalışan kişidir.\n• III. Öğretmen: Köy okulunun müdürü/öğretmeni olup ihtiyar heyetinin doğal üyesidir.\n• IV. Doktor: Köylerde doğal üye statüsünde doktor bulunmaz (Sağlık ocakları aile hekimliği sistemindedir).\n\n💡 KPSS HAFIZA KARTI:\nKöy Teşkilatı Organları:\n• **Köy Derneği:** Köydeki tüm seçmenlerin oluşturduğu en geniş organdır; Muhtarı ve İhtiyar Heyetini seçer.\n• **Köy Muhtarı:** Köyün başı ve tüzel kişiliğin temsilcisidir.\n• **İhtiyar Meclisi:** Karar organıdır. Doğal üyeleri: **İMAM ve ÖĞRETMEN**.",
