    "topic": "Yazım Kuralları / Birleşik Sözcüklerin Yazımı",
    "questionText": "(I) Yağmur dindikten sonra gökyüzünde beliren renk cümbüşü herkesi büyüledi.\n(II) Çocuklar sevinçle sokaklara dökülüp etrafa neşe saçtılar.\n(III) Kimileri ise gök kuşağına doğru koşup onun altından geçmek istiyordu.\n(IV) Doğa, sunduğu bu eşsiz manzarayla insanları kendine bir kez daha hayran bıraktı.\n(V) Akşamüzeri güneş batarken gökyüzü kızıla boyandı.\n\nBu parçadaki numaralanmış cümlelerin hangisinde bir yazım yanlışı vardır?",
    "options": {
      "A": "I",
      "B": "II",
      "C": "III",
      "D": "IV",
      "E": "V"
    },
    "markedAnswer": "C",
    "correctAnswer": "C",
    "explanation": "✅ DOĞRU CEVAP: C) III (\"gök kuşağına\")\nTDK Yazım Kılavuzu'na göre: İki veya daha fazla kelimenin bir araya gelmesiyle yeni bir doğa olayı, gök cismi veya somut kavramı karşılayan birleşik sözcükler bitişik yazılır. Gökyüzündeki optik ışık kırılmasıyla oluşan renkli kemeri ifade eden sözcük **BİRLEŞİK OLARAK \"gökkuşağı\"** şeklinde yazılmalıdır. Cümlede ayrı yazılarak (\"gök kuşağına\") yazım yanlışı yapılmıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) I. Cümle: \"renk cümbüşü\" doğru yazılmıştır (ayrı yazılır).\n• B) II. Cümle: \"sevinçle sokaklara dökülüp\" imla ve noktalama açısından tamamen doğrudur.\n• D) IV. Cümle: \"bir kez daha\" ifadesi doğrudur.\n• E) V. Cümle: \"Akşamüzeri\" doğru yazılmıştır (Somut bir yer bildirmeyen -alt, -üst, -üzeri sözleri bitişik yazılır).\n\n💡 KPSS HAFIZA KARTI:\nYazım Kuralları Püf Noktaları:\n• **-altı / -üstü / -üzeri Sözcükleri:** Somut yer bildirmiyorsa BİTİŞİK yazılır: *Akşamüzeri, ayaküstü, bilinçaltı, suçüstü, olağanüstü*.\n• **Gök Cisimleri ve Hadiseleri:** *Gökkuşağı (bitişik), gökdelen (bitişik), Samanyolu (bitişik), Kutup Yıldızı (ayrı ve büyük)*.",
