    "explanation": "✅ DOĞRU CEVAP: B) Almanya\nBirleşmiş Milletler Güvenlik Konseyi'nin (BMGK) toplam 15 üyesi vardır. Bunların 10 tanesi 2 yıllığına seçilen geçici üyeler, 5 tanesi ise kararları tek başına **VETO ETME YETKİSİ BULUNAN DAİMÎ ÜYELERDİR**. Kodlaması **FİRÇA**dır: **Fransa, İngiltere, Rusya, Çin ve ABD**. Almanya II. Dünya Savaşı'nı kaybeden taraf olduğu için BM'nin kurucu daimi üyeleri arasında yer almamıştır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Fransa: BMGK daimi üyesidir ve veto hakkı vardır.\n• B) Almanya: BMGK daimi üyesi değildir; geçici üyelik yapabilir.\n• C) İngiltere: BMGK daimi üyesidir ve veto hakkı vardır.\n• D) Rusya: BMGK daimi üyesidir (Sovyetler Birliği'nin mirasçısı).\n• E) Çin: BMGK daimi üyesidir ve veto yetkisine sahiptir.\n\n💡 KPSS HAFIZA KARTI:\nBM Güvenlik Konseyi Daimî Üyeleri (Veto Hakkı Olan 5 Ülke):\n• Şifre: **FİRÇA**\n  - **F**ransa\n  - **İ**ngiltere\n  - **R**usya\n  - **Ç**in\n  - **A**BD\n• Cumhurbaşkanı'nın **\"Dünya 5'ten Büyüktür\"** doktrini bu 5 ülkenin veto tekelini ifade eder.",
