    "explanation": "✅ DOĞRU CEVAP: B) Tapınaklar Vadisi\nİtalya'nın Sicilya adasındaki Agrigento kentinde yer alan, antik Yunan Dor mimarisinin günümüze en sağlam ulaşmış yapılarından biri olan Concordia Tapınağı, UNESCO Dünya Mirası Listesi'ndeki **TAPINAKLAR VADİSİ (Valle dei Templi)** içinde yer almaktadır.\n\n🔍 ÇELDİRİCİLERİN ANALİZİ (1 Soru 5 Bilgi):\n• A) Krallar Vadisi: Mısır'da Luksor yakınlarında Tutankhamun gibi antik firavunların kaya mezarlarının bulunduğu vadidir.\n• C) Kelebekler Vadisi: Türkiye'de Muğla'nın Fethiye ilçesinde Babadağ eteklerindeki kanyon vadidir.\n• D) Göreme Vadisi: Nevşehir'de peribacaları ve kayadan oyma tarihi kiliselerin bulunduğu UNESCO miras alanıdır.\n• E) Ihlara Vadisi: Aksaray'da Melendiz Çayı'nın kanyon vadisidir.\n\n💡 KPSS HAFIZA KARTI:\nDünya Mirası Vadiler ve Tapınaklar:\n• Tapınaklar Vadisi (Concordia) -> **İtalya (Sicilya / Agrigento)**\n• Krallar Vadisi -> **Mısır (Luksor)**\n• Petra Antik Kenti -> **Ürdün**\n• Taç Mahal -> **Hindistan (Agra)**\n• El Hamra Sarayı -> **İspanya (Granada)**",
